INSERT INTO `categories` (`id`, `name`, `slug`, `parent_id`, `level`, `description`, `seo_title`, `seo_description`, `meta_description`, `image`, `order_position`, `status`, `is_producer`) VALUES
(14, 'Rượu vang Ý', 'ruou-vang-y', 16, 1, '<div class=\"coll_title \" style=\"text-align: center; margin-bottom: 20px; font-family: Roboto, sans-serif; font-size: 14px;\"><h1 style=\"margin: 0px; font-weight: 600; line-height: 1.4; font-size: 24px; color: rgb(201, 75, 60); text-transform: uppercase; letter-spacing: 1px;\">Rượu Vang Ý</h1></div><div class=\"descrip_coll content_coll add_apper active\" style=\"max-height: initial; overflow: hidden; position: relative; font-family: Roboto, sans-serif; font-size: 14px;\"><p data-path-to-node=\"0\" style=\"margin: 0px 0px 15px;\">Nước Ý (Italy) kiêu hãnh là quốc gia sản xuất rượu vang lớn nhất thế giới về mặt sản lượng, đồng thời sở hữu chiều sâu văn hóa làm vang lâu đời bậc nhất hành tinh. Vai trò của Ý trong lịch sử rượu vang châu Âu là không thể thay thế, trải dài từ thời cổ đại đến kỷ nguyên hiện đại. Điều gì làm rượu vang Ý khác biệt hoàn toàn với phần còn lại? Đó chính là sự đa dạng sinh học ngoạn mục với hơn 500 giống nho bản địa và triết lý làm vang tôn trọng tuyệt đối bản sắc thổ nhưỡng. Chính cấu trúc đanh nét, độ acid sống động và hương vị mặn mòi nguyên bản đã khiến vang Ý trở thành sự lựa chọn tối cao được giới sưu tầm fine wine và các bàn tiệc fine dining thượng lưu yêu thích.</p><p data-path-to-node=\"1\" style=\"margin: 0px 0px 15px; text-align: center;\"><img alt=\"Rượu vang ý\" data-thumb=\"original\" original-height=\"593\" original-width=\"800\" src=\"https://bizweb.dktcdn.net/100/441/574/files/ruou-vang-y.jpg?v=1778227190723\" style=\"border: 0px; max-width: 100%; height: 801px; width: 1080px;\"></p><p data-path-to-node=\"1\" style=\"margin: 0px 0px 15px; text-align: center;\">Rượu vang ý</p><hr data-path-to-node=\"2\" style=\"box-sizing: content-box; height: 0px; overflow: visible; border-width: 1px 0px 0px; border-style: solid none none; border-color: rgba(0, 0, 0, 0.1) currentcolor currentcolor;\"><h2 data-path-to-node=\"3\" style=\"line-height: 1.4;\">Rượu Vang Ý Là Gì?</h2><h3 data-path-to-node=\"4\" style=\"line-height: 1.4;\">Lịch sử phát triển của rượu vang Ý</h3><p data-path-to-node=\"5\" style=\"margin: 0px 0px 15px;\">Lịch sử của rượu vang Ý gắn liền với sự hưng thịnh của Đế chế La Mã cổ đại. Người La Mã cổ đại (Ancient Roman) chính là những người đã có công hoàn thiện kỹ thuật trồng nho, đưa văn hóa thưởng thức rượu vang (wine culture Italy) lan tỏa ra khắp lục địa châu Âu. Vùng đất Ý thời bấy giờ được người Hy Lạp cổ gọi bằng cái tên đầy tôn kính: <i data-index-in-node=\"338\" data-path-to-node=\"5\">Oenotria</i> – vùng đất của những vạt nho bất tận.</p><h3 data-path-to-node=\"6\" style=\"line-height: 1.4;\">Vai trò của Ý trong ngành rượu vang thế giới</h3><p data-path-to-node=\"7\" style=\"margin: 0px 0px 15px;\">Ngày nay, Ý không chỉ đứng đầu thế giới về khối lượng sản xuất mà còn là ngọn hải đăng dẫn dắt xu hướng vang thế giới. Ngành công nghiệp rượu vang Ý là sự kết hợp khổng lồ giữa hàng vạn điền trang gia đình nhỏ lẻ cho đến các tập đoàn lớn, đóng góp một phần trọng yếu vào GDP và bản sắc văn hóa quốc gia.</p><h3 data-path-to-node=\"8\" style=\"line-height: 1.4;\">Điều gì làm rượu vang Ý nổi tiếng?</h3><p data-path-to-node=\"9\" style=\"margin: 0px 0px 15px;\">Sự nổi tiếng của rượu vang Ý đến từ tính độc bản. Thay vì chạy theo các giống nho quốc tế phổ biến, nước Ý tập trung bảo tồn các giống nho bản địa cổ xưa, tạo ra những hương vị mà bạn không thể tìm thấy ở bất kỳ nơi nào khác trên trái đất.</p><h3 data-path-to-node=\"10\" style=\"line-height: 1.4;\">Phong cách Old World đặc trưng của vang Ý</h3><p data-path-to-node=\"11\" style=\"margin: 0px 0px 15px;\">Là một đại diện thuần túy của trường phái Cựu Lục Địa (Old World style), <a _ngcontent-ng-c2426467660=\"\" _nghost-ng-c2223583066=\"\" data-hveid=\"0\" data-ved=\"0CAAQ_4QMahgKEwiX5Nmo28GUAxUAAAAAHQAAAAAQkwM\" decode-data-ved=\"1\" externallink=\"\" href=\"https://wine1855.vn/ruou-vang-y\" jslog=\"197247;track:generic_click,impression,attention;BardVeMetadataKey:[[&quot;r_a676af715e4a6d53&quot;,&quot;c_89c8a0d3232d2d39&quot;,null,&quot;rc_40dd422610747ce5&quot;,null,null,&quot;vi&quot;,null,1,null,null,1,0]]\" rel=\"noopener\" target=\"_blank\" style=\"color: rgb(23, 57, 99); text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">rượu vang Ý</a> không chú trọng vào vị ngọt ngào bùng nổ của trái cây như vang Tân Thế Giới. Họ tập trung vào nghệ thuật làm vang truyền thống: đề cao cấu trúc chặt chẽ, độ acid tự nhiên cao, hương vị khoáng đạt và chiều sâu hương vị trầm ấm phát triển theo thời gian.</p><p data-path-to-node=\"11\" style=\"margin: 0px 0px 15px; text-align: center;\"><img alt=\"Lịch sử phát triển rượu vang Ý\" data-thumb=\"original\" original-height=\"720\" original-width=\"1080\" src=\"https://bizweb.dktcdn.net/100/441/574/files/ruou-vang-y-lich-su-phat-trien.jpg?v=1779073509141\" style=\"border: 0px; max-width: 100%; height: auto;\"></p><p data-path-to-node=\"11\" style=\"margin: 0px 0px 15px; text-align: center;\">Lịch sử phát triển rượu vang Ý</p><hr data-path-to-node=\"12\" style=\"box-sizing: content-box; height: 0px; overflow: visible; border-width: 1px 0px 0px; border-style: solid none none; border-color: rgba(0, 0, 0, 0.1) currentcolor currentcolor;\"><h2 data-path-to-node=\"13\" style=\"line-height: 1.4;\">Đặc Điểm Nổi Bật Của Rượu Vang Ý</h2><h3 data-path-to-node=\"14\" style=\"line-height: 1.4;\">Độ acid cao và khả năng pairing tuyệt vời</h3><p data-path-to-node=\"15\" style=\"margin: 0px 0px 15px;\">Đặc tính sinh học nổi bật nhất của vang Ý là hàm lượng acid tự nhiên rất cao. Điều này không phải là nhược điểm mà là một món quà biến chúng trở thành dòng vang thân thiện nhất với thực phẩm (Food-friendly wine). Độ acid sắc bén giúp làm sạch vòm miệng, cắt đứt các lớp chất béo ngậy của phô mai và thịt mỡ một cách hoàn hảo.</p><h3 data-path-to-node=\"16\" style=\"line-height: 1.4;\">Cấu trúc tannin đặc trưng</h3><p data-path-to-node=\"17\" style=\"margin: 0px 0px 15px;\">Vang đỏ Ý sở hữu cấu trúc tannin vô cùng đa dạng: từ sự se khít, uy nghiêm bướng bỉnh của nho Nebbiolo cho đến sự nhung mượt, đầy đặn dạt dào của nho Primitivo.</p><h3 data-path-to-node=\"18\" style=\"line-height: 1.4;\">Phong cách thanh lịch và phức hợp</h3><p data-path-to-node=\"19\" style=\"margin: 0px 0px 15px;\">Rượu vang Ý luôn phảng phất những nốt hương của đất ấm (earthy notes), thảo mộc dại, da thuộc cổ kính xen lẫn nốt hương khoáng chất (mineral character), mang lại một phong vị vô cùng thanh lịch, kín đáo và đa tầng vị.</p><h3 data-path-to-node=\"20\" style=\"line-height: 1.4;\">Tiềm năng lưu trữ lâu năm</h3><p data-path-to-node=\"21\" style=\"margin: 0px 0px 15px;\">Những chai vang Ý thuộc phân hạng cao cấp sở hữu một bộ khung xương acid và tannin cực kỳ bền vững, cho phép chúng nằm yên tiến hóa trong hầm rượu từ 20 đến 50 năm mà vẫn giữ vẹn nguyên sức sống mãnh liệt.</p><p data-path-to-node=\"21\" style=\"margin: 0px 0px 15px; text-align: center;\"><img alt=\"Đặc điểm rượu vang Ý\" data-thumb=\"original\" original-height=\"720\" original-width=\"1080\" src=\"https://bizweb.dktcdn.net/100/441/574/files/dac-diem-ruou-vang-y.jpg?v=1779073373695\" style=\"border: 0px; max-width: 100%; height: auto;\"></p><p data-path-to-node=\"21\" style=\"margin: 0px 0px 15px; text-align: center;\">Đặc điểm rượu vang Ý</p><hr data-path-to-node=\"22\" style=\"box-sizing: content-box; height: 0px; overflow: visible; border-width: 1px 0px 0px; border-style: solid none none; border-color: rgba(0, 0, 0, 0.1) currentcolor currentcolor;\"><h2 data-path-to-node=\"23\" style=\"line-height: 1.4;\">Hệ Thống Phân Hạng Rượu Vang Ý</h2><p data-path-to-node=\"24\" style=\"margin: 0px 0px 15px;\">Để kiểm soát chất lượng và bảo vệ người tiêu dùng, luật rượu vang Ý (Wine law Italy) thiết lập một hệ thống phân hạng hình kim tự tháp nghiêm ngặt (Classification hierarchy):</p><ul data-path-to-node=\"26\" style=\"margin-bottom: 0px; list-style: inherit; padding-left: 25px;\"><li><p data-path-to-node=\"26,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"26,0,0\" style=\"font-weight: bolder;\">DOCG (Denominación de Origen Calificada y Garantizada):</span> Cấp độ cao cấp nhất. Rượu phải tuân thủ những quy định khắt khe nhất về sản lượng, giống nho, thời gian ủ gỗ và phải trải qua một hội đồng nếm thử của chính phủ trước khi được dán niêm phong đặc biệt trên cổ chai.</p></li><li><p data-path-to-node=\"26,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"26,1,0\" style=\"font-weight: bolder;\">DOC (Denominación de Origen Controlada):</span> Phân hạng chuẩn mực, đảm bảo rượu được làm từ một vùng địa lý cụ thể (Appellation system) theo những công thức truyền thống lâu đời.</p></li><li><p data-path-to-node=\"26,2,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"26,2,0\" style=\"font-weight: bolder;\">IGT (Indicazione Geografica Tipica):</span> Phân hạng dành cho các dòng vang mang tính chỉ dẫn địa lý vùng lớn. Đây là \"sân chơi\" của sự sáng tạo, nơi các nhà làm vang sử dụng các giống nho quốc tế để tạo ra những tuyệt tác mà không bị bó buộc bởi luật DOC/DOCG cũ kỹ.</p></li><li><p data-path-to-node=\"26,3,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"26,3,0\" style=\"font-weight: bolder;\">Vino da Tavola (Table Wine):</span> Dòng vang bàn phổ thông hằng ngày, không hiển thị giống nho hay vùng trồng trên nhãn chai.</p></li></ul><p data-path-to-node=\"26,3,0\" style=\"margin: 0px 0px 15px; text-align: center;\"><img alt=\"Phân hạng rượu vang Ý\" data-thumb=\"original\" original-height=\"720\" original-width=\"1080\" src=\"https://bizweb.dktcdn.net/100/441/574/files/phan-hang-vang-y.jpg?v=1779073328325\" style=\"border: 0px; max-width: 100%; height: auto;\"></p><p data-path-to-node=\"26,3,0\" style=\"margin: 0px 0px 15px; text-align: center;\">Phân hạng rượu vang Ý</p><h3 data-path-to-node=\"27\" style=\"line-height: 1.4;\">Cách đọc nhãn chai vang Ý</h3><p data-path-to-node=\"28\" style=\"margin: 0px 0px 15px;\">Nhãn chai vang Ý luôn hiển thị theo thứ tự: Tên nhà sản xuất ➔ Tên dòng rượu ➔ Giống nho hoặc Tên vùng trồng ➔ Năm thu hoạch (Vintage) ➔ Cấp bậc phân hạng (DOCG/DOC/IGT).</p><hr data-path-to-node=\"29\" style=\"box-sizing: content-box; height: 0px; overflow: visible; border-width: 1px 0px 0px; border-style: solid none none; border-color: rgba(0, 0, 0, 0.1) currentcolor currentcolor;\"><h2 data-path-to-node=\"30\" style=\"line-height: 1.4;\">Các Vùng Rượu Vang Nổi Tiếng Của Ý</h2><h3 data-path-to-node=\"31\" style=\"line-height: 1.4;\">Tuscany – Trái tim của vang Ý</h3><p data-path-to-node=\"32\" style=\"margin: 0px 0px 15px;\"><a _ngcontent-ng-c2426467660=\"\" _nghost-ng-c2223583066=\"\" data-hveid=\"0\" data-ved=\"0CAAQ_4QMahgKEwiX5Nmo28GUAxUAAAAAHQAAAAAQlQM\" decode-data-ved=\"1\" externallink=\"\" href=\"https://www.google.com/search?q=https://wine1855.vn/ruou-vang-y-tuscany\" jslog=\"197247;track:generic_click,impression,attention;BardVeMetadataKey:[[&quot;r_a676af715e4a6d53&quot;,&quot;c_89c8a0d3232d2d39&quot;,null,&quot;rc_40dd422610747ce5&quot;,null,null,&quot;vi&quot;,null,1,null,null,1,0]]\" rel=\"noopener\" target=\"_blank\" style=\"color: rgb(23, 57, 99); text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Vang Tuscany</a> là vùng đất của những đồi đất sét ngập nắng, những hàng cây bách diệp kiêu hãnh và là thánh địa của giống nho Sangiovese.</p><ul data-path-to-node=\"33\" style=\"margin-bottom: 0px; list-style: inherit; padding-left: 25px;\"><li><p data-path-to-node=\"33,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"33,0,0\" style=\"font-weight: bolder;\">Chianti Classico:</span> Dòng vang đỏ mang tính biểu tượng với biểu tượng chú gà trống đen, sở hữu vị chua thanh thoát và hương quả anh đào đỏ rực rỡ.</p></li><li><p data-path-to-node=\"33,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"33,1,0\" style=\"font-weight: bolder;\">Brunello di Montalcino:</span> Đỉnh cao quý tộc của Tuscany, làm từ 100% nho Sangiovese Grosso, ủ gỗ sồi ròng rã, cấu trúc uy nghiêm tuyệt đỉnh.</p></li><li><p data-path-to-node=\"33,2,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"33,2,0\" style=\"font-weight: bolder;\">Super Tuscan:</span> Những tuyệt phẩm phá vỡ quy tắc truyền thống, phối trộn theo phong cách Bordeaux blend đầy kiêu hãnh.</p></li></ul><h3 data-path-to-node=\"34\" style=\"line-height: 1.4;\">Piedmont – Quê hương của Barolo</h3><p data-path-to-node=\"35\" style=\"margin: 0px 0px 15px;\">Nằm dưới chân dãy Alps phía Tây Bắc, Piedmont sở hữu khí hậu sương mù khô lạnh, nơi sản sinh ra giống nho Nebbiolo vĩ đại. Hai cái tên <span data-index-in-node=\"135\" data-path-to-node=\"35\" style=\"font-weight: bolder;\">Barolo</span> (Vua của rượu vang) và <span data-index-in-node=\"165\" data-path-to-node=\"35\" style=\"font-weight: bolder;\">Barbaresco</span> (Nữ hoàng) là những báu vật fine wine của thế giới với cấu trúc tannin uy lực và hương vị hoa hồng, nhựa đường quý phái.</p><h3 data-path-to-node=\"36\" style=\"line-height: 1.4;\">Veneto – Vùng vang Amarone nổi tiếng</h3><p data-path-to-node=\"37\" style=\"margin: 0px 0px 15px;\">Nằm ở phía Đông Bắc, Veneto nổi tiếng toàn cầu nhờ dòng vang <span data-index-in-node=\"61\" data-path-to-node=\"37\" style=\"font-weight: bolder;\">Amarone della Valpolicella</span> – được làm từ những chùm nho phơi khô héo (Appassimento) để cô đọng đường và hương vị, tạo ra chất rượu đậm đặc, nồng độ cồn cao và texture mượt mà như nhung.</p><h3 data-path-to-node=\"38\" style=\"line-height: 1.4;\">Puglia – Thiên đường Primitivo</h3><p data-path-to-node=\"39\" style=\"margin: 0px 0px 15px;\">Nằm ở gót giày nước Ý, <a _ngcontent-ng-c2426467660=\"\" _nghost-ng-c2223583066=\"\" data-hveid=\"0\" data-ved=\"0CAAQ_4QMahgKEwiX5Nmo28GUAxUAAAAAHQAAAAAQlgM\" decode-data-ved=\"1\" externallink=\"\" href=\"https://wine1855.vn/puglia\" jslog=\"197247;track:generic_click,impression,attention;BardVeMetadataKey:[[&quot;r_a676af715e4a6d53&quot;,&quot;c_89c8a0d3232d2d39&quot;,null,&quot;rc_40dd422610747ce5&quot;,null,null,&quot;vi&quot;,null,1,null,null,1,0]]\" rel=\"noopener\" target=\"_blank\" style=\"color: rgb(23, 57, 99); text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">vang Puglia</a> ngập tràn ánh nắng ấm áp của Địa Trung Hải. Thổ nhưỡng đất đỏ giàu sắt nơi đây là thiên đường của giống nho <span data-index-in-node=\"143\" data-path-to-node=\"39\" style=\"font-weight: bolder;\">Primitivo</span> và <span data-index-in-node=\"156\" data-path-to-node=\"39\" style=\"font-weight: bolder;\">Negroamaro</span>, cho ra đời những chai vang đỏ đậm đà, mạnh mẽ, giàu vị mứt quả ngọt ngào vô cùng dễ uống.</p><h3 data-path-to-node=\"40\" style=\"line-height: 1.4;\">Sicily &amp; Friuli Venezia Giulia</h3><ul data-path-to-node=\"41\" style=\"margin-bottom: 0px; list-style: inherit; padding-left: 25px;\"><li><p data-path-to-node=\"41,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"41,0,0\" style=\"font-weight: bolder;\">Sicily:</span> Hòn đảo Địa Trung Hải với đất đá núi lửa Etna độc đáo, tạo ra những dòng vang đỏ và trắng có vị khói và khoáng đạt sắc nét.</p></li><li><p data-path-to-node=\"41,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"41,1,0\" style=\"font-weight: bolder;\">Friuli Venezia Giulia:</span> Vùng đất phía Bắc chuyên sản sinh ra những chai vang trắng cao cấp, đanh nét, giàu hương hoa cỏ và có cấu trúc vô cùng tinh tế.</p></li></ul><hr data-path-to-node=\"42\" style=\"box-sizing: content-box; height: 0px; overflow: visible; border-width: 1px 0px 0px; border-style: solid none none; border-color: rgba(0, 0, 0, 0.1) currentcolor currentcolor;\"><h2 data-path-to-node=\"43\" style=\"line-height: 1.4;\">Các Giống Nho Nổi Tiếng Của Ý</h2><ul data-path-to-node=\"44\" style=\"margin-bottom: 0px; list-style: inherit; padding-left: 25px;\"><li><p data-path-to-node=\"44,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"44,0,0\" style=\"font-weight: bolder;\">Sangiovese:</span> Linh hồn của Tuscany, mang hương vị anh đào đỏ, thảo mộc khô, độ acid cao và tannin se khít, cực kỳ ăn ý với các món sốt cà chua.</p></li><li><p data-path-to-node=\"44,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"44,1,0\" style=\"font-weight: bolder;\">Nebbiolo:</span> Giống nho quý phái của Piedmont, màu sắc nhạt như Pinot Noir nhưng lại sở hữu lượng tannin và acid khổng lồ, gầm rú với làn hương hoa hồng khô, hắc ín và nấm truffle.</p></li><li><p data-path-to-node=\"44,2,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"44,2,0\" style=\"font-weight: bolder;\">Primitivo:</span> Giống nho hoàng gia của Puglia, mang phong cách đậm đà, lượng cồn dồi dào, hương vị mâm xôi, sô-cô-la ngọt ngào và tannin êm ái, rất được ưa chuộng tại thị trường Việt Nam.</p></li><li><p data-path-to-node=\"44,3,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"44,3,0\" style=\"font-weight: bolder;\">Barbera &amp; Montepulciano:</span> Những giống nho phổ biến miền Trung và Bắc Ý, mang phong cách mềm mại, mọng nước, acid tươi mát và cực kỳ dễ uống hằng ngày.</p></li><li><p data-path-to-node=\"44,4,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"44,4,0\" style=\"font-weight: bolder;\">Corvina:</span> Nền tảng cốt lõi tạo nên hương vị đậm đặc, đa tầng của dòng vang Amarone huyền thoại vùng Veneto.</p></li></ul><hr data-path-to-node=\"45\" style=\"box-sizing: content-box; height: 0px; overflow: visible; border-width: 1px 0px 0px; border-style: solid none none; border-color: rgba(0, 0, 0, 0.1) currentcolor currentcolor;\"><h2 data-path-to-node=\"46\" style=\"line-height: 1.4;\">Những Dòng Rượu Vang Ý Nổi Tiếng Nhất</h2><ul data-path-to-node=\"47\" style=\"margin-bottom: 0px; list-style: inherit; padding-left: 25px;\"><li><p data-path-to-node=\"47,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"47,0,0\" style=\"font-weight: bolder;\">Barolo DOCG:</span> Cấu trúc uy nghiêm, đậm mạnh vị khoáng, tannin se khít, phù hợp cho giới sành sỏi lưu trữ lâu năm.</p></li><li><p data-path-to-node=\"47,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"47,1,0\" style=\"font-weight: bolder;\">Brunello di Montalcino DOCG:</span> Phong cách quý tộc, phức hợp hương da thuộc, thuốc lá và anh đào đen sâu lắng.</p></li><li><p data-path-to-node=\"47,2,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"47,2,0\" style=\"font-weight: bolder;\">Chianti Classico DOCG:</span> Thanh lịch, food-friendly, lý tưởng cho mọi bữa tiệc fine dining châu Âu.</p></li><li><p data-path-to-node=\"47,3,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"47,3,0\" style=\"font-weight: bolder;\">Amarone della Valpolicella:</span> Đậm đặc, béo ngậy, nồng độ cồn cao (15-16%), hậu vị kéo dài bất tận với vị sô-cô-la đắng và trái cây khô.</p></li><li><p data-path-to-node=\"47,4,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"47,4,0\" style=\"font-weight: bolder;\">Super Tuscan:</span> Đỉnh cao sáng tạo, mượt mà và quyến rũ chuẩn mực quốc tế.</p></li><li><p data-path-to-node=\"47,5,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"47,5,0\" style=\"font-weight: bolder;\">Primitivo di Manduria:</span> <a _ngcontent-ng-c2426467660=\"\" _nghost-ng-c2223583066=\"\" data-hveid=\"0\" data-ved=\"0CAAQ_4QMahgKEwiX5Nmo28GUAxUAAAAAHQAAAAAQlwM\" decode-data-ved=\"1\" externallink=\"\" href=\"https://wine1855.vn/negroamaro\" jslog=\"197247;track:generic_click,impression,attention;BardVeMetadataKey:[[&quot;r_a676af715e4a6d53&quot;,&quot;c_89c8a0d3232d2d39&quot;,null,&quot;rc_40dd422610747ce5&quot;,null,null,&quot;vi&quot;,null,1,null,null,1,0]]\" rel=\"noopener\" target=\"_blank\" style=\"color: rgb(23, 57, 99); text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Rượu vang Negroamaro</a> và <a _ngcontent-ng-c2426467660=\"\" _nghost-ng-c2223583066=\"\" data-hveid=\"0\" data-ved=\"0CAAQ_4QMahgKEwiX5Nmo28GUAxUAAAAAHQAAAAAQmAM\" decode-data-ved=\"1\" externallink=\"\" href=\"https://wine1855.vn/primitivo\" jslog=\"197247;track:generic_click,impression,attention;BardVeMetadataKey:[[&quot;r_a676af715e4a6d53&quot;,&quot;c_89c8a0d3232d2d39&quot;,null,&quot;rc_40dd422610747ce5&quot;,null,null,&quot;vi&quot;,null,1,null,null,1,0]]\" rel=\"noopener\" target=\"_blank\" style=\"color: rgb(23, 57, 99); text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">rượu vang Primitivo</a> của Manduria là những dòng vang đậm đà, ngọt ngào hương mứt quả, nồng nộ cồn ấm áp, cực kỳ thích hợp cho khẩu vị người Việt và làm quà biếu cao cấp.</p></li></ul></div>', 'Khám phá rượu vang Ý chính hãng | RUOUCHAT.vn', 'Rượu vang Ý luôn phảng phất những nốt hương của đất ấm (earthy notes), thảo mộc dại, da thuộc cổ kính xen lẫn nốt hương khoáng chất (mineral character), mang lại một phong vị vô cùng thanh lịch, kín đáo và đa tầng vị.', NULL, 'uploads/category/20260527_100214_6a165eb657007.webp', 0, 1, 0);
INSERT INTO `categories` (`id`, `name`, `slug`, `parent_id`, `level`, `description`, `seo_title`, `seo_description`, `meta_description`, `image`, `order_position`, `status`, `is_producer`) VALUES
(15, 'Rượu vang New Zealand', 'ruou-vang-new-zealand', 16, 1, '', '', '', NULL, '', 0, 1, 0),
(16, 'Rượu vang', 'ruou-vang', 0, 0, '<p data-path-to-node=\"2\">Rượu vang là sự kết tinh của thổ nhưỡng (Terroir), giống nho và di sản văn hóa làm vang lâu đời. Tại RUOUCHAT.vn, chúng tôi xây dựng bộ sưu tập rượu vang dựa trên các tiêu chuẩn kỹ thuật nghiêm ngặt, từ việc đánh giá dữ liệu niên vụ (vintage reports) đến phân tích cấu trúc tannin và độ acid của từng chai rượu. Chúng tôi không chỉ cung cấp sản phẩm, mà còn chia sẻ kiến thức chuyên sâu về đặc tính vùng miền, từ những chai vang đỏ đậm đà vùng Bordeaux đến vang trắng khoáng đạt của New World.</p><p data-path-to-node=\"3\">Với tư cách là chuyên gia, RUOUCHAT.vn cam kết mỗi chai vang khi đến tay quý khách hàng đều được lưu trữ trong điều kiện nhiệt độ và độ ẩm tối ưu. Điều này đảm bảo sự toàn vẹn của hương vị, giúp giới mộ điệu cảm nhận trọn vẹn sự phức hợp và tiềm năng lão hóa của từng dòng rượu vang cao cấp. Hãy khám phá danh mục tuyển chọn tại RUOUCHAT.vn để nâng tầm trải nghiệm thưởng thức, nơi giá trị thực sự của di sản làm vang được khẳng định qua sự am hiểu sâu sắc và tiêu chuẩn chất lượng vượt trội.</p>', 'Rượu Vang Nhập Khẩu Chính Hãng | Đẳng Cấp | RUOUCHAT.vn', 'Khám phá thế giới rượu vang thượng hạng từ các vùng Terroir danh tiếng tại RUOUCHAT.vn. Cam kết chất lượng, thông tin chuyên sâu, chuẩn vị cho người sành sỏi. Mua ngay!', NULL, '', 0, 1, 0),
(17, 'Rượu mạnh', 'ruou-manh', 0, 0, '', '', '', NULL, '', 0, 1, 0),
(19, 'Sản phẩm khác', 'san-pham-khac', 0, 0, '<p>ok</p>', '', '', NULL, '', 0, 1, 0),
(20, 'Bia Bỉ', 'bia-bi', 38, 1, '<p data-path-to-node=\"2\">Bia Bỉ là đỉnh cao của nghệ thuật ủ bia thủ công thế giới, nổi danh với sự đa dạng phong cách từ dòng Trappist đậm đà, bia tu viện (Abbey) đến các dòng lên men tự nhiên (Lambic) phức hợp. Điểm khác biệt nằm ở kỹ thuật lên men nổi đặc trưng và quá trình lên men lại trong chai, tạo nên lớp bọt mịn cùng cấu trúc hương vị vô cùng tinh tế, sâu lắng. Tại RUOUCHAT.vn, chúng tôi tuyển chọn những nhà sản xuất bia di sản lâu đời, đảm bảo mỗi sản phẩm đều phản ánh trung thực quy trình nấu bia truyền thống với nguyên liệu thượng hạng.</p><p data-path-to-node=\"3\">Đội ngũ chuyên gia tại RUOUCHAT.vn thấu hiểu giá trị của sự trải nghiệm nên luôn cung cấp thông tin chi tiết về độ cồn, phương pháp sản xuất và gợi ý kết hợp ẩm thực tối ưu. Chúng tôi cam kết bảo quản sản phẩm ở điều kiện nhiệt độ nghiêm ngặt để lưu giữ trọn vẹn sự cân bằng giữa vị đắng nhẹ của hoa bia và nét ngọt ngào của mạch nha. Hãy khám phá danh mục bia Bỉ tuyển chọn tại website để tận hưởng trải nghiệm thưởng thức đẳng cấp, nơi sự sang trọng và giá trị văn hóa được tôn vinh một cách chuyên nghiệp nhất qua từng lựa chọn của RUOUCHAT.vn.</p>', 'Bia Bỉ Nhập Khẩu Chính Hãng | Đẳng Cấp Thượng Hạng | RUOUCHAT.vn', 'Khám phá thế giới bia Bỉ thượng hạng tại RUOUCHAT.vn. Tuyển chọn dòng bia tu viện, bia lên men tự nhiên chuẩn vị truyền thống. Đặt hàng ngay để nhận ưu đãi tốt nhất!', NULL, '', 0, 1, 0),
(24, 'rf', 'rf', 23, 2, '', '', '', NULL, '', 0, 1, 0),
(26, 'Rượu Vang Chile', 'ruou-vang-chile', 16, 1, '<p>Rượu vang Chile nổi danh toàn cầu nhờ sự kết hợp hoàn hảo giữa khí hậu Địa Trung Hải ôn hòa và thổ nhưỡng độc đáo từ dãy Andes. Những giống nho chủ đạo như Cabernet Sauvignon, Carménère hay Chardonnay tại đây được chăm sóc kỹ lưỡng, tạo nên cấu trúc tannin mượt mà và hương vị trái cây đậm đà đặc trưng. Tại RUOUCHAT.vn, chúng tôi tuyển chọn khắt khe những chai vang từ các nhà làm vang danh tiếng, đảm bảo mỗi sản phẩm đều phản ánh trung thực bản sắc của vùng Terroir Chile. Mỗi dòng vang đều đi kèm thông tin chi tiết về niên vụ (vintage) và tiêu chuẩn bảo quản, giúp khách hàng có cái nhìn chuyên sâu trước khi lựa chọn. Chúng tôi tự hào mang đến trải nghiệm thưởng thức vang đích thực, tối ưu cho cả nhu cầu biếu tặng và sưu tầm. Với nền tảng kiến thức chuyên môn, RUOUCHAT.vn cam kết mỗi chai vang Chile đến tay khách hàng đều đạt chuẩn chất lượng quốc tế cao nhất. Khám phá ngay danh mục vang Chile tuyển chọn để nâng tầm trải nghiệm thưởng thức của riêng bạn.</p>', 'Rượu Vang Chile Nhập Khẩu Chính Hãng | Cao Cấp | RUOUCHAT.vn', 'Khám phá bộ sưu tập rượu vang Chile thượng hạng từ các vùng Central Valley, Maipo. Đảm bảo chất lượng, chứng nhận nhập khẩu. Đặt mua tại RUOUCHAT.vn ngay hôm nay!', NULL, '', 0, 1, 0),
(27, 'Rượu Vang Úc', 'ruou-vang-uc', 16, 1, '<p data-path-to-node=\"2\">Rượu vang Úc đại diện cho phong cách \"Thế giới mới\" với sự bùng nổ của hương vị trái cây chín mọng và cấu trúc rượu đầy đặn. Những giống nho chủ đạo như Shiraz từ vùng Barossa Valley hay Chardonnay từ Margaret River đã định hình nên bản sắc riêng biệt, mang lại trải nghiệm thưởng thức cân bằng và dễ tiếp cận cho người dùng. Khác với các quy định khắt khe của châu Âu, vang Úc chú trọng vào kỹ thuật sản xuất hiện đại và sự tự do trong sáng tạo, cho phép mỗi chai rượu phản ánh trung thực đặc trưng thổ nhưỡng của từng vùng.</p><p data-path-to-node=\"3\">Tại RUOUCHAT.vn, chúng tôi tuyển chọn kỹ lưỡng những dòng vang Úc từ các nhà sản xuất danh tiếng, đảm bảo mỗi sản phẩm đều có đầy đủ thông tin về kỹ thuật (technical data) và niên vụ. Chúng tôi thấu hiểu giá trị của sự trải nghiệm nên luôn cam kết cung cấp những chai vang có chất lượng ổn định, từ những dòng vang đỏ mạnh mẽ với tầng hương gia vị, socola đến các loại vang trắng tươi mát, khoáng đạt. Hãy để RUOUCHAT.vn đồng hành cùng bạn trong hành trình chinh phục thế giới vang Úc đẳng cấp, nơi sự sang trọng kết hợp cùng phong cách sống hiện đại.</p>', 'Rượu Vang Úc Thượng Hạng | Nhập Khẩu Chính Hãng | RUOUCHAT.vn', 'Khám phá tinh hoa rượu vang Úc tại RUOUCHAT.vn. Từ Shiraz đậm đà đến Chardonnay thanh lịch, chúng tôi mang đến những chai vang chuẩn Terroir, uy tín và đẳng cấp nhất.', NULL, '', 0, 1, 0),
(28, 'Rượu Vang Tây Ban Nha', 'ruou-vang-tay-ban-nha', 16, 1, '<p data-path-to-node=\"2\">Rượu vang Tây Ban Nha mang trong mình chiều sâu văn hóa từ những vùng làm vang lâu đời như Rioja, Ribera del Duero hay Priorat. Với việc sử dụng các giống nho bản địa đặc trưng như Tempranillo, Garnacha và kỹ thuật ủ sồi tinh xảo, vang Tây Ban Nha đạt được sự cân bằng tuyệt đối giữa hương vị trái cây chín đỏ và các nốt hương gia vị, thảo mộc phức hợp. Hệ thống phân hạng khắt khe theo thời gian ủ (Crianza, Reserva, Gran Reserva) chính là bảo chứng cho chất lượng ổn định và tiềm năng lão hóa vượt trội của dòng vang này.</p><p data-path-to-node=\"3\">Tại RUOUCHAT.vn, chúng tôi thấu hiểu giá trị của Terroir trong từng chai vang, từ đó tuyển chọn khắt khe những sản phẩm phản ánh trung thực bản sắc của vùng đất. Mỗi chai vang được cung cấp tại đây đều đi kèm thông tin chi tiết về niên vụ và kỹ thuật sản xuất, giúp giới mộ điệu dễ dàng lựa chọn được hương vị ưng ý nhất. Chúng tôi cam kết mang đến trải nghiệm thưởng thức vang đích thực, nơi sự sang trọng hòa quyện cùng phong cách sống thượng lưu. Hãy khám phá bộ sưu tập vang Tây Ban Nha tại RUOUCHAT.vn để tận hưởng tiêu chuẩn chất lượng cao cấp nhất.</p>', 'Rượu Vang Tây Ban Nha Nhập Khẩu Chính Hãng | RUOUCHAT.vn', 'Khám phá tinh hoa rượu vang Tây Ban Nha tại RUOUCHAT.vn. Tuyển chọn các dòng vang Rioja, Ribera del Duero thượng hạng với chất lượng chuẩn chuyên gia. Mua ngay!', NULL, '', 0, 1, 0),
(29, 'Rượu Vang Bồ Đào Nha', 'ruou-vang-bo-dao-nha', 16, 1, '<p data-path-to-node=\"2\">Rượu vang Bồ Đào Nha sở hữu bản sắc riêng biệt nhờ hệ thống giống nho bản địa phong phú và kỹ thuật làm vang lâu đời, đặc biệt là tại vùng Douro Valley. Không chỉ nổi danh với dòng vang cường hóa Port trứ danh, Bồ Đào Nha còn tạo ấn tượng mạnh mẽ qua những chai vang đỏ đậm đà, cấu trúc tannin vững chắc và hương vị khoáng chất sắc nét từ thổ nhưỡng đất đá phiến độc đáo. Tại RUOUCHAT.vn, chúng tôi tuyển chọn tỉ mỉ các dòng vang phản ánh chân thực di sản văn hóa này, đảm bảo mỗi sản phẩm đều được kiểm định kỹ thuật khắt khe.</p><p data-path-to-node=\"3\">Chúng tôi hiểu rằng mỗi niên vụ (vintage) đều kể một câu chuyện khác nhau về Terroir, do đó RUOUCHAT.vn luôn cung cấp dữ liệu chi tiết giúp khách hàng am hiểu sâu sắc về phong cách vang mình lựa chọn. Từ sự tinh tế của các dòng vang vùng Dão đến nét quyến rũ khó cưỡng của vang Alentejo, mọi chai rượu tại cửa hàng đều cam kết giữ trọn vẹn đặc tính nguyên bản. Hãy để RUOUCHAT.vn nâng tầm trải nghiệm thưởng thức của bạn bằng những lựa chọn vang Bồ Đào Nha đẳng cấp, nơi sự sang trọng hòa quyện cùng chiều sâu lịch sử làm vang đích thực.</p>', 'Rượu Vang Bồ Đào Nha Nhập Khẩu Chính Hãng | RUOUCHAT.vn', 'Khám phá thế giới vang Bồ Đào Nha đẳng cấp tại RUOUCHAT.vn. Từ vang Port huyền thoại đến vang đỏ Douro thượng hạng, đảm bảo nguồn gốc, chuẩn chuyên gia. Mua ngay!', NULL, '', 0, 1, 0),
(30, 'Rượu Vang Mỹ', 'ruou-vang-my', 16, 1, '<p data-path-to-node=\"2\">Rượu vang Mỹ, đặc biệt từ vùng Napa Valley, nổi danh thế giới với phong cách đậm đà, cấu trúc tannin mạnh mẽ và hương vị trái cây chín nồng nàn. Sự kết hợp giữa thổ nhưỡng đa dạng và kỹ thuật làm vang tiên tiến đã tạo nên những chai Cabernet Sauvignon đạt chuẩn mực quốc tế về độ phức hợp. Tại RUOUCHAT.vn, chúng tôi tuyển chọn kỹ lưỡng từng niên vụ, đảm bảo mỗi chai vang phản ánh chân thực bản sắc của từng tiểu vùng (AVA) danh tiếng.</p><p data-path-to-node=\"3\">Với dữ liệu kỹ thuật chi tiết, chúng tôi cam kết mang đến trải nghiệm thưởng thức vang Mỹ đích thực cho khách hàng chuyên môn và sưu tầm. Mỗi sản phẩm tại RUOUCHAT.vn đều được bảo quản trong điều kiện chuẩn mực, giữ trọn vẹn sự tinh túy và phong cách đẳng cấp của các nhà làm vang huyền thoại. Hãy khám phá bộ sưu tập vang Mỹ tại website để nâng tầm trải nghiệm thưởng thức của bạn với những lựa chọn chất lượng vượt trội.</p>', 'Rượu Vang Mỹ Cao Cấp | Nhập Khẩu Chính Hãng | RUOUCHAT.vn', 'Khám phá tinh hoa rượu vang Mỹ tại RUOUCHAT.vn. Tuyển chọn vang Napa Valley thượng hạng, đậm đà chuẩn Terroir. Đảm bảo chất lượng và uy tín cho giới mộ điệu.', NULL, '', 0, 1, 0),
(31, 'Rượu Whisky', 'ruou-whisky', 17, 1, '<p data-path-to-node=\"2\">Rượu Whisky là tinh hoa của kỹ thuật chưng cất bậc thầy, nơi thời gian ủ trong thùng gỗ sồi tạo nên sự phức hợp của hương vị khói, gia vị và gỗ sồi cháy đặc trưng. Tại RUOUCHAT.vn, chúng tôi chú trọng vào các dòng Whisky từ những vùng sản xuất danh tiếng như Scotch Whisky, Japanese Whisky với tiêu chuẩn nghiêm ngặt về quy trình đóng chai và độ tuổi (aging). Mỗi dòng sản phẩm đều được tuyển chọn để đảm bảo sự cân bằng giữa nồng độ cồn và tầng hương vị sâu lắng, đáp ứng kỳ vọng của những người sưu tầm khó tính nhất.</p><p data-path-to-node=\"3\">Chúng tôi cung cấp dữ liệu kỹ thuật chi tiết về quy trình sản xuất, nguồn nước và loại thùng ủ, giúp quý khách hàng hiểu rõ giá trị thực sự trong từng giọt rượu. RUOUCHAT.vn cam kết mang đến những lựa chọn Whisky thượng hạng, bảo quản trong điều kiện chuẩn mực để giữ trọn vẹn bản sắc của nhà chưng cất. Hãy khám phá bộ sưu tập Whisky tại cửa hàng để nâng tầm trải nghiệm thưởng thức, nơi sự sang trọng và di sản văn hóa hòa quyện trong từng ly rượu đẳng cấp.</p>', 'Rượu Whisky Nhập Khẩu Chính Hãng | Thượng Hạng | RUOUCHAT.vn', 'Khám phá thế giới Whisky đẳng cấp tại RUOUCHAT.vn. Tuyển chọn Single Malt, Blended Whisky từ các nhà chưng cất danh tiếng. Đảm bảo chất lượng, chuẩn vị chuyên gia.', NULL, '', 0, 1, 0),
(32, 'Rượu Cognac', 'ruou-cognac', 17, 1, '<p data-path-to-node=\"2\">Cognac là đỉnh cao của nghệ thuật chưng cất rượu mạnh từ nho tại vùng Charente, Pháp, trải qua quá trình lão hóa khắt khe trong thùng gỗ sồi Limousin. Sự kết hợp giữa các loại \"eau-de-vie\" từ những tiểu vùng terroir danh tiếng như Grande Champagne hay Petite Champagne tạo nên cấu trúc hương vị phức hợp, với các tầng hương trái cây sấy, mật ong, và gia vị nồng nàn. Tại RUOUCHAT.vn, chúng tôi tuyển chọn những dòng Cognac thượng hạng dựa trên tiêu chuẩn phân loại nghiêm ngặt và niên vụ đặc trưng.</p><p data-path-to-node=\"3\">Đội ngũ chuyên gia tại RUOUCHAT.vn thấu hiểu giá trị của sự tinh tế, vì vậy mỗi chai Cognac đều được kiểm định kỹ lưỡng về kỹ thuật chưng cất và độ chín muồi. Chúng tôi cung cấp dữ liệu chi tiết về đặc tính hương vị, giúp giới mộ điệu cảm nhận trọn vẹn di sản nghệ thuật từ các nhà làm rượu lâu đời. Hãy khám phá bộ sưu tập Cognac tại cửa hàng để nâng tầm trải nghiệm thưởng thức, nơi sự sang trọng và lịch sử làm rượu hòa quyện trong từng giọt rượu đẳng cấp.</p>', 'Rượu Cognac Thượng Hạng | Nhập Khẩu Chính Hãng | RUOUCHAT.vn', 'Khám phá thế giới Cognac tinh túy tại RUOUCHAT.vn. Tuyển chọn các dòng VS, VSOP, XO từ vùng Charente trứ danh. Đảm bảo chất lượng, chuẩn vị chuyên gia. Mua ngay!', NULL, '', 0, 1, 0),
(33, 'Rượu Rum', 'ruou-rum', 17, 1, '<p data-path-to-node=\"2\">Rượu Rum là hiện thân của sự kết tinh từ mật mía hoặc nước mía lên men, mang trong mình linh hồn của vùng Caribe với những tầng hương vị độc đáo từ trái cây nhiệt đới, caramel và gia vị cay nồng. Tại RUOUCHAT.vn, chúng tôi tuyển chọn khắt khe các dòng Rum từ phương pháp chưng cất nồi tĩnh (pot still) truyền thống đến cột chưng cất hiện đại, đảm bảo giữ trọn vẹn đặc tính Terroir của vùng nguyên liệu. Việc kiểm soát kỹ thuật ủ trong các loại thùng gỗ sồi khác nhau giúp mỗi sản phẩm đạt được cấu trúc hương vị phức hợp, đáp ứng tiêu chuẩn khắt khe cho cả người thưởng thức trực tiếp và pha chế chuyên nghiệp.</p><p data-path-to-node=\"3\">Chúng tôi cung cấp dữ liệu kỹ thuật chi tiết về quy trình sản xuất, giúp giới mộ điệu hiểu rõ giá trị của từng niên vụ và phương pháp lão hóa đặc thù. RUOUCHAT.vn không chỉ phân phối sản phẩm mà còn là nơi chia sẻ kiến thức chuyên sâu về di sản rượu Rum toàn cầu. Hãy khám phá danh mục rượu Rum tuyển chọn tại website để tận hưởng trải nghiệm thưởng thức đẳng cấp, nơi sự sang trọng và hương vị nguyên bản được bảo tồn hoàn hảo trong từng chai vang, đảm bảo sự an tâm tuyệt đối cho khách hàng.</p>', 'Rượu Rum Cao Cấp Nhập Khẩu | Hương Vị Đẳng Cấp | RUOUCHAT.vn', 'Khám phá bộ sưu tập rượu Rum thượng hạng tại RUOUCHAT.vn. Từ dòng Light Rum thanh tao đến Dark Rum đậm đà, cam kết chuẩn chất lượng, nguồn gốc và tư vấn chuyên gia.', NULL, '', 0, 1, 0),
(34, 'Rượu Vermouth', 'ruou-vermouth', 17, 1, '<p data-path-to-node=\"2\">Vermouth là loại vang cường hóa đặc biệt, được tẩm ướp cùng hỗn hợp botanicals, thảo mộc, vỏ cây và gia vị quý, tạo nên cấu trúc hương vị vô cùng phức tạp và quyến rũ. Tại RUOUCHAT.vn, chúng tôi phân loại Vermouth dựa trên phong cách truyền thống gồm Dry (trắng, khô) và Sweet (đỏ, ngọt), phản ánh đúng di sản từ các vùng làm vang danh tiếng như Torino hay Chambéry. Mỗi dòng sản phẩm được tuyển chọn tại đây đều đảm bảo sự cân bằng hoàn hảo giữa vị đắng nhẹ của thảo mộc và độ sâu của cốt vang nền, mang lại tiêu chuẩn cao nhất cho cả nhu cầu thưởng thức nguyên chất (neat) hoặc làm nền tảng cốt lõi trong các dòng Cocktail kinh điển.</p><p data-path-to-node=\"3\">Chúng tôi cung cấp thông tin chi tiết về kỹ thuật sản xuất, giúp giới mộ điệu am hiểu sâu sắc về sự khác biệt giữa các dòng sản phẩm và cách phối trộn tối ưu. RUOUCHAT.vn cam kết mỗi chai Vermouth đến tay khách hàng đều được lưu trữ trong điều kiện chuẩn mực, giữ trọn vẹn đặc tính nguyên bản của từng nhà sản xuất. Hãy khám phá danh mục Vermouth tuyển chọn tại website để nâng tầm trải nghiệm thưởng thức của bạn, nơi chất lượng và kiến thức chuyên môn hòa quyện trong từng lựa chọn đẳng cấp.</p>', 'Rượu Vermouth Thượng Hạng | Nhập Khẩu Chính Hãng | RUOUCHAT.vn', 'Khám phá thế giới Vermouth tinh tế tại RUOUCHAT.vn. Tuyển chọn các dòng vang thảo mộc đẳng cấp từ Ý và Pháp, đảm bảo chất lượng, chuẩn vị chuyên gia cho mọi cocktail.', NULL, '', 0, 1, 0),
(35, 'Rượu mạnh Scotland', 'ruou-manh-scotland', 17, 1, '<p data-path-to-node=\"4\">Rượu mạnh Scotland, hay còn gọi là Scotch Whisky, là biểu tượng của nghệ thuật chưng cất với quy trình sản xuất nghiêm ngặt từ lúa mạch mạch nha, nước tinh khiết và nấm men. Sự khác biệt về Terroir giữa các vùng như Speyside, Islay hay Highlands tạo nên hồ sơ hương vị đa dạng, từ nét thanh tao, hoa cỏ đến vị khói than bùn đặc trưng đầy mạnh mẽ. Tại RUOUCHAT.vn, chúng tôi tuyển chọn khắt khe các dòng Single Malt và Blended Whisky dựa trên tiêu chuẩn niên vụ và kỹ thuật ủ trong thùng gỗ sồi, đảm bảo mỗi giọt rượu đều đạt độ cân bằng và phức hợp tối ưu.</p><p data-path-to-node=\"5\">Chúng tôi cung cấp dữ liệu kỹ thuật chi tiết về quy trình đóng chai và đặc tính từng vùng, giúp quý khách hàng am hiểu sâu sắc về di sản rượu mạnh Scotland. RUOUCHAT.vn cam kết mỗi sản phẩm đều được bảo quản trong điều kiện chuẩn mực, giữ trọn vẹn bản sắc nguyên bản từ các nhà chưng cất huyền thoại. Hãy khám phá bộ sưu tập tại website để nâng tầm trải nghiệm thưởng thức của bạn, nơi sự sang trọng và giá trị truyền thống được tôn vinh một cách chuyên nghiệp nhất.</p>', 'Rượu Mạnh Scotland Cao Cấp | Whisky Chính Hãng | RUOUCHAT.vn', 'Khám phá thế giới Whisky Scotland thượng hạng tại RUOUCHAT.vn. Tuyển chọn Single Malt từ các vùng chưng cất danh tiếng, đảm bảo chất lượng, chuẩn vị chuyên gia. Mua ngay!', NULL, '', 0, 1, 0),
(36, 'Rượu mạnh Pháp', 'ruou-manh-phap', 17, 1, '<p data-path-to-node=\"2\">Rượu mạnh Pháp, tiêu biểu là Cognac và Armagnac, là đỉnh cao của nghệ thuật chưng cất dựa trên nguyên liệu nho và quá trình ủ trong thùng gỗ sồi lâu năm. Sự khác biệt về thổ nhưỡng (Terroir) tại các vùng Charente hay Gascony mang lại cấu trúc hương vị phức hợp, từ nốt hương hoa cỏ thanh tao đến sự đậm đà của trái cây sấy và gia vị. Tại RUOUCHAT.vn, chúng tôi tuyển chọn kỹ lưỡng những dòng rượu mạnh danh tiếng, đảm bảo thông số kỹ thuật chuẩn xác về tuổi rượu (VS, VSOP, XO) và quy trình sản xuất truyền thống.</p><p data-path-to-node=\"3\">Đội ngũ chuyên gia tại RUOUCHAT.vn chú trọng vào việc cung cấp dữ liệu minh bạch, giúp giới mộ điệu am hiểu sâu sắc về di sản chưng cất của từng nhà làm rượu Pháp. Chúng tôi cam kết bảo quản sản phẩm trong điều kiện tối ưu, giữ trọn vẹn sự tinh túy và phong cách lịch lãm trong từng giọt rượu đến tay khách hàng. Hãy khám phá bộ sưu tập rượu mạnh Pháp tại website để nâng tầm trải nghiệm thưởng thức, nơi giá trị văn hóa và tiêu chuẩn thượng hạng hòa quyện hoàn hảo.</p>', 'Rượu Mạnh Pháp Cao Cấp | Cognac & Armagnac | RUOUCHAT.vn', 'Khám phá thế giới rượu mạnh Pháp đẳng cấp tại RUOUCHAT.vn. Tuyển chọn Cognac, Armagnac thượng hạng với quy trình chưng cất truyền thống. Trải nghiệm tinh hoa ngay!', NULL, '', 0, 1, 0),
(37, 'Rượu Gin', 'ruou-gin', 17, 1, '<p data-path-to-node=\"2\">Rượu Gin là sự kết tinh nghệ thuật giữa rượu nền trung tính và hỗn hợp thực vật (botanicals) đặc trưng, với nốt hương chủ đạo từ quả bách xù (juniper berries). Tại RUOUCHAT.vn, chúng tôi chú trọng vào sự đa dạng của các dòng Gin từ phong cách truyền thống London Dry sắc sảo đến các biến thể hiện đại chứa đựng các loại thảo mộc, gia vị và vỏ cam quýt phức hợp. Mỗi chai Gin được tuyển chọn đều phải đáp ứng tiêu chuẩn khắt khe về kỹ thuật chưng cất, đảm bảo giữ trọn vẹn độ thanh khiết và sự cân bằng hoàn hảo trong từng tầng hương vị.</p><p data-path-to-node=\"3\">Chúng tôi cung cấp dữ liệu chuyên sâu về xuất xứ và thành phần thực vật, giúp giới mộ điệu am hiểu rõ giá trị của từng thương hiệu. RUOUCHAT.vn không chỉ phân phối sản phẩm mà còn là người dẫn dắt, mang đến giải pháp tối ưu cho nhu cầu thưởng thức neat hoặc phối trộn cocktail đẳng cấp. Mỗi sản phẩm khi đến tay khách hàng đều được kiểm định về nguồn gốc và bảo quản tối ưu, khẳng định vị thế của chuyên gia rượu vang và rượu mạnh hàng đầu. Hãy khám phá bộ sưu tập Gin tại website để trải nghiệm sự sang trọng và tinh tế trong từng ly rượu.</p>', 'Rượu Gin Nhập Khẩu Chính Hãng | Thơm Ngon Đẳng Cấp | RUOUCHAT.vn', 'Khám phá thế giới Gin tinh tế tại RUOUCHAT.vn. Tuyển chọn các dòng London Dry, Botanical Gin thượng hạng, đảm bảo chất lượng, chuẩn vị chuyên gia cho mọi cocktail.', NULL, '', 0, 1, 0);
INSERT INTO `categories` (`id`, `name`, `slug`, `parent_id`, `level`, `description`, `seo_title`, `seo_description`, `meta_description`, `image`, `order_position`, `status`, `is_producer`) VALUES
(38, 'Bia ngoại', 'bia-ngoai', 0, 0, '<p data-path-to-node=\"4\">Bia ngoại tại RUOUCHAT.vn được tuyển chọn từ những nhà máy bia lâu đời tại Bỉ, Đức và Tiệp Khắc, nơi di sản sản xuất bia thủ công (craft brewing) được lưu giữ qua nhiều thế hệ. Chúng tôi tập trung vào các dòng bia tu viện, bia lúa mì và bia vàng với độ tinh khiết cao, đảm bảo cấu trúc hương vị nguyên bản từ hoa bia (hops), mạch nha (malt) và men bia đặc trưng. Mỗi dòng bia đều đi kèm thông tin chi tiết về độ cồn (ABV), độ đắng (IBU) và quy trình lên men, giúp người sành sỏi dễ dàng lựa chọn đúng gu thưởng thức.</p><p data-path-to-node=\"5\">Chúng tôi hiểu rằng bia ngoại không chỉ là thức uống giải khát mà còn là trải nghiệm văn hóa. Do đó, RUOUCHAT.vn cam kết bảo quản sản phẩm ở điều kiện nhiệt độ nghiêm ngặt nhằm duy trì sự ổn định của bọt và hương vị tinh tế nhất. Với đội ngũ chuyên gia am hiểu sâu sắc về kỹ thuật thưởng thức, chúng tôi sẵn sàng tư vấn cách kết hợp bia với ẩm thực (food pairing) để tôn vinh sự sang trọng. Hãy khám phá danh mục bia ngoại tại website để tận hưởng chất lượng đẳng cấp, nơi sự uy tín của RUOUCHAT.vn luôn là ưu tiên hàng đầu cho khách hàng.</p>', 'Bia Ngoại Nhập Khẩu Cao Cấp | Thưởng Thức Đẳng Cấp | RUOUCHAT.vn', 'Khám phá bộ sưu tập bia ngoại thượng hạng từ các quốc gia danh tiếng tại RUOUCHAT.vn. Đảm bảo nguồn gốc chính hãng, chuẩn vị chuyên gia. Đặt mua trải nghiệm ngay!', NULL, '', 0, 1, 0),
(39, 'Bia Đức', 'bia-duc', 38, 1, '<p data-path-to-node=\"2\">Bia Đức là biểu tượng của nghệ thuật ủ bia lâu đời, tuân thủ nghiêm ngặt Luật Tinh khiết (Reinheitsgebot) từ năm 1516, chỉ sử dụng nước, mạch nha, hoa bia và men bia. Tại RUOUCHAT.vn, chúng tôi tuyển chọn các dòng bia từ vùng Bavaria danh tiếng, nơi đặc trưng thổ nhưỡng và quy trình lên men truyền thống tạo nên cấu trúc hương vị đặc biệt. Từ những chai bia lúa mì (Weissbier) thanh tao, đầy hương trái cây đến dòng bia Lager đậm đà, mỗi sản phẩm đều phản ánh trung thực di sản văn hóa bia Đức đích thực.</p><p data-path-to-node=\"3\">Đội ngũ chuyên gia tại RUOUCHAT.vn hiểu rằng giá trị của một chai bia nằm ở độ tươi mới và kỹ thuật bảo quản chuyên sâu. Chúng tôi cam kết kiểm soát chặt chẽ điều kiện lưu kho để giữ trọn vẹn lớp bọt mịn, độ cân bằng giữa vị đắng hoa bia và vị ngọt tự nhiên của mạch nha. Khám phá danh mục bia Đức tuyển chọn để nâng tầm trải nghiệm thưởng thức, khẳng định gu thẩm mỹ tinh tế cùng sự an tâm về chất lượng từ chuyên gia rượu mạnh uy tín hàng đầu.</p>', 'Bia Đức Nhập Khẩu Chính Hãng | Thượng Hạng | RUOUCHAT.vn', 'Khám phá tinh hoa bia Đức tại RUOUCHAT.vn. Tuyển chọn các dòng bia thủ công chuẩn vị, quy trình ủ khắt khe. Đặt mua ngay để tận hưởng hương vị đẳng cấp thế giới!', NULL, '', 0, 1, 0),
(40, 'Bia Tiệp', 'bia-tiep', 38, 1, '<p data-path-to-node=\"2\">Bia Tiệp là di sản văn hóa thế giới với phong cách Pilsner trứ danh, nổi bật nhờ kỹ thuật nấu bia từ hoa bia Saaz và quy trình ủ dài ngày trong hầm lạnh. Đặc tính nổi trội của dòng bia này là cấu trúc cân bằng hoàn hảo giữa độ đắng thanh thoát từ hoa bia và vị ngọt dịu đậm đà của mạch nha tuyển chọn, tạo nên lớp bọt dày mịn và dư vị sảng khoái kéo dài. Tại RUOUCHAT.vn, chúng tôi chú trọng vào việc tuyển chọn những nhà sản xuất bia di sản lâu đời tại Cộng hòa Séc, đảm bảo mỗi sản phẩm đều giữ trọn vẹn đặc tính nguyên bản (Authenticity) của vùng Terroir.</p><p data-path-to-node=\"3\">Đội ngũ chuyên gia tại RUOUCHAT.vn hiểu rõ tầm quan trọng của kỹ thuật bảo quản đối với dòng bia có độ nhạy cảm cao này, cam kết cung cấp sản phẩm trong tình trạng lý tưởng nhất. Chúng tôi không chỉ cung cấp thức uống mà còn chia sẻ kiến thức chuyên sâu về độ cồn (ABV), độ đắng (IBU) và các gợi ý kết hợp ẩm thực (food pairing) để tôn vinh tối đa hương vị. Hãy khám phá danh mục bia Tiệp tại website để nâng tầm trải nghiệm thưởng thức của bạn với tiêu chuẩn chất lượng vượt trội. RUOUCHAT.vn luôn là điểm đến tin cậy cho những người mộ điệu bia Tiệp đích thực.</p>', 'Bia Tiệp Nhập Khẩu Thượng Hạng | Chuẩn Vị | RUOUCHAT.vn', 'Trải nghiệm tinh hoa bia Tiệp tại RUOUCHAT.vn. Tuyển chọn dòng Pilsner chuẩn vị, chất lượng thượng hạng, cam kết chính hãng. Đặt mua ngay để tận hưởng vị bia đẳng cấp!', NULL, '', 0, 1, 0),
(41, 'Bia Hà Lan', 'bia-ha-lan', 38, 1, '<p data-path-to-node=\"2\">Bia Hà Lan từ lâu đã khẳng định vị thế trên thị trường quốc tế nhờ kỹ thuật lên men Lager sắc sảo và tiêu chuẩn sản xuất nghiêm ngặt. Sự kết hợp giữa nguồn nước tinh khiết, mạch nha thượng hạng và hoa bia tuyển chọn tạo nên những dòng bia có độ cân bằng hoàn hảo, mang đến cảm giác sảng khoái và dư vị đậm đà đặc trưng. Tại RUOUCHAT.vn, chúng tôi đặc biệt chú trọng vào việc tuyển chọn những thương hiệu di sản và các dòng bia thủ công độc đáo, đảm bảo mỗi sản phẩm đều giữ trọn vẹn đặc tính nguyên bản.</p><p data-path-to-node=\"3\">Đội ngũ chuyên gia tại RUOUCHAT.vn luôn cung cấp dữ liệu minh bạch về độ cồn (ABV), độ đắng (IBU) và quy trình sản xuất, giúp quý khách hàng dễ dàng lựa chọn sản phẩm phù hợp với khẩu vị cá nhân. Chúng tôi cam kết bảo quản bia trong môi trường nhiệt độ tối ưu để lưu giữ lớp bọt mịn cùng hương vị tươi mới nhất khi đến tay khách hàng. Hãy khám phá danh mục bia Hà Lan tại website để nâng tầm trải nghiệm thưởng thức, nơi sự sang trọng và giá trị đẳng cấp luôn được RUOUCHAT.vn ưu tiên đặt lên hàng đầu.</p>', 'Bia Hà Lan Nhập Khẩu Thượng Hạng | Chính Hãng | RUOUCHAT.vn', 'Khám phá thế giới bia Hà Lan đẳng cấp tại RUOUCHAT.vn. Tuyển chọn dòng Lager, bia thủ công thượng hạng, cam kết chất lượng và chuẩn vị chuyên gia. Đặt mua ngay!', NULL, '', 0, 1, 0),
(42, 'Lager', 'lager', 38, 1, '<p data-path-to-node=\"2\">Lager là dòng bia được lên men chìm ở nhiệt độ thấp, nổi danh với đặc tính trong suốt, hương vị thanh khiết và sự cân bằng hoàn hảo giữa mạch nha cùng hoa bia. Tại RUOUCHAT.vn, chúng tôi đặc biệt chú trọng vào kỹ thuật bảo quản để duy trì sự ổn định của lớp bọt mịn và độ giòn (crispness) đặc trưng, đảm bảo mỗi chai Lager khi đến tay khách hàng đều giữ trọn vẹn sự tươi mới.</p><p data-path-to-node=\"3\">Mỗi sản phẩm đều được kiểm định khắt khe về thông số độ cồn (ABV) và độ đắng (IBU), phản ánh đúng phong cách truyền thống từ các nhà sản xuất Lager danh tiếng. Đội ngũ chuyên gia tại RUOUCHAT.vn không chỉ phân phối sản phẩm mà còn mang đến dữ liệu chuyên sâu về quy trình ủ lạnh, giúp người mộ điệu thấu hiểu giá trị của dòng bia \"thế giới mới\" này. Hãy khám phá danh mục Lager tại website để tận hưởng trải nghiệm thưởng thức sảng khoái và sang trọng với tiêu chuẩn chất lượng cao cấp nhất.</p>', 'Rượu Bia Lager Nhập Khẩu Thượng Hạng | Chuẩn Vị | RUOUCHAT.vn', 'Khám phá dòng bia Lager đẳng cấp tại RUOUCHAT.vn. Tuyển chọn hương vị tươi mát, chuẩn kỹ thuật lên men lạnh từ các thương hiệu quốc tế. Đặt hàng trải nghiệm ngay!', NULL, '', 0, 1, 0),
(43, 'Ale', 'ale', 38, 1, '<p data-path-to-node=\"2\">Lager là dòng bia được lên men chìm ở nhiệt độ thấp, nổi danh với đặc tính trong suốt, hương vị thanh khiết và sự cân bằng hoàn hảo giữa mạch nha cùng hoa bia. Tại RUOUCHAT.vn, chúng tôi đặc biệt chú trọng vào kỹ thuật bảo quản để duy trì sự ổn định của lớp bọt mịn và độ giòn (crispness) đặc trưng, đảm bảo mỗi chai Lager khi đến tay khách hàng đều giữ trọn vẹn sự tươi mới.</p><p data-path-to-node=\"3\">Mỗi sản phẩm đều được kiểm định khắt khe về thông số độ cồn (ABV) và độ đắng (IBU), phản ánh đúng phong cách truyền thống từ các nhà sản xuất Lager danh tiếng. Đội ngũ chuyên gia tại RUOUCHAT.vn không chỉ phân phối sản phẩm mà còn mang đến dữ liệu chuyên sâu về quy trình ủ lạnh, giúp người mộ điệu thấu hiểu giá trị của dòng bia \"thế giới mới\" này. Hãy khám phá danh mục Lager tại website để tận hưởng trải nghiệm thưởng thức sảng khoái và sang trọng với tiêu chuẩn chất lượng cao cấp nhất.</p>', 'Rượu Bia Lager Nhập Khẩu Thượng Hạng | Chuẩn Vị | RUOUCHAT.vn', 'Khám phá dòng bia Lager đẳng cấp tại RUOUCHAT.vn. Tuyển chọn hương vị tươi mát, chuẩn kỹ thuật lên men lạnh từ các thương hiệu quốc tế. Đặt hàng trải nghiệm ngay!', NULL, '', 0, 1, 0),
(44, 'Bia IPA', 'bia-ipa', 38, 1, '<p data-path-to-node=\"2\">Bia IPA (India Pale Ale) là biểu tượng của phong trào bia thủ công, nổi bật nhờ hàm lượng hoa bia cao tạo nên tầng hương vị bùng nổ của cam quýt, trái cây nhiệt đới và thông xanh. Tại RUOUCHAT.vn, chúng tôi tuyển chọn khắt khe các dòng IPA từ phong cách West Coast sắc sảo đến New England IPA mềm mịn, đảm bảo độ cân bằng giữa vị đắng đặc trưng (IBU) và hậu vị mạch nha tinh tế. Sự khác biệt trong kỹ thuật \"dry-hopping\" được chúng tôi chú trọng để giữ trọn vẹn tinh chất thực vật, mang đến trải nghiệm thưởng thức chuẩn mực cho người mộ điệu.</p><p data-path-to-node=\"3\">Đội ngũ chuyên gia tại RUOUCHAT.vn thấu hiểu giá trị của sự tươi mới, do đó mọi sản phẩm đều được kiểm soát nghiêm ngặt về điều kiện lưu trữ và niên vụ đóng chai. Chúng tôi cung cấp dữ liệu kỹ thuật minh bạch về các giống hoa bia (hops profile) và độ cồn, giúp quý khách hàng dễ dàng khám phá thế giới IPA phức hợp. Hãy để RUOUCHAT.vn dẫn dắt bạn qua hành trình thưởng thức bia đẳng cấp, nơi sự am hiểu về kỹ thuật nấu bia hòa quyện cùng gu thưởng thức sang trọng trong từng lựa chọn thượng hạng.</p>', 'Bia IPA Nhập Khẩu Thượng Hạng | Đậm Đà | RUOUCHAT.vn', 'Trải nghiệm bia IPA đỉnh cao tại RUOUCHAT.vn. Tuyển chọn các dòng bia thủ công đậm đà, hương thơm hoa bia bùng nổ, chuẩn vị chuyên gia. Đặt mua thưởng thức ngay hôm nay!', NULL, '', 0, 1, 0),
(45, 'Vùng nổi tiếng', 'vung-noi-tieng', 0, 0, '', '', '', NULL, '', 0, 1, 0),
(46, 'Loại nho', 'loai-nho', 0, 0, '<p>Loại nho</p>', '', '', NULL, '', 0, 1, 0),
(50, 'Nhà sản xuất', 'nha-san-xuat', 0, 0, '', '', '', NULL, '', 0, 1, 0),
(54, 'Domaine Faiveley', 'domaine-faiveley', 50, 1, 'Pháp\r\n', '', '', NULL, '', 0, 1, 1),
(55, 'Château Dauzac', 'chteau-dauzac', 50, 1, '', '', '', NULL, '', 0, 1, 1),
(56, 'Altano Douro', 'altano-douro', 50, 1, '<h1>Rượu Vang Altano Douro</h1>\r\n<p>\r\n  <b>Altano Douro</b>\r\n  là thương hiệu vang danh tiếng thuộc tập đoàn\r\n  <b>Symington Family Estates</b>\r\n  , biểu tượng cho nghệ thuật làm vang hiện đại tại vùng thung lũng\r\n  <b>Douro DOC (Bồ Đào Nha)</b>\r\n  .\r\n  <sup></sup>\r\n  Được phối trộn tinh tế từ các giống nho bản địa cao cấp như\r\n  <b>Touriga Franca, Tinta Roriz và Tinta Barroca</b>\r\n  , Altano Douro chinh phục giới thưởng thức nhờ cấu trúc đậm đà (full-bodied), hương thơm quyến rũ của mận chín, quả\r\n  mọng đen hòa quyện cùng nốt hoa dại và gia vị cay ấm áp.\r\n  <sup></sup>\r\n  Sự kết hợp mượt mà giữa chất tannin mượt như lụa và độ chua tự nhiên cân bằng mang lại hậu vị sâu lắng, bền bỉ.\r\n</p>\r\n<p></p>\r\n<p>\r\n  Tại\r\n  <b>RUOUCHAT.vn</b>\r\n  , chúng tôi tuyển chọn kỹ lưỡng từng niên hiệu Altano Douro từ các dòng vang đỏ cổ điển, vang hữu cơ (Organic) cho đến\r\n  dòng Reserva trưởng thành trong thùng gỗ sồi Pháp.\r\n  <sup></sup>\r\n  Sản phẩm được bảo quản chuẩn nhiệt độ Cellar khắt khe, cam kết nhập khẩu chính ngạch đầy đủ chứng nhận nguồn gốc\r\n  (CO/CQ).\r\n  <b>RUOUCHAT.vn</b>\r\n  tự hào là cầu nối uy tín mang giá trị Terroir Douro độc đáo cùng trải nghiệm thưởng thức đỉnh cao đến tận tay những\r\n  tín đồ vang Việt.\r\n</p>\r\n', 'Rượu Vang Altano Douro Nhập Khẩu Chính Hãng | RUOUCHAT.vn', 'Khám phá Altano Douro từ Symington Family - Nhà sản xuất dòng vang Bồ Đào Nha đẳng cấp. Mua ngay vang Altano chính hãng, chuẩn vị Terroir Douro tại RUOUCHAT.vn!', NULL, '', 0, 1, 1),
(57, 'Caviro', 'caviro', 50, 1, 'Caviro là hợp tác xã rượu vang hàng đầu nước Ý, nổi danh với quy trình kiểm soát chất lượng khắt khe từ vườn nho đến khi đóng chai. Với triết lý tôn trọng thổ nhưỡng (terroir) và ứng dụng kỹ thuật sản xuất hiện đại, Caviro mang đến những dòng vang có độ ổn định tuyệt vời, làm nổi bật đặc tính của các giống nho bản địa như Sangiovese hay Trebbiano. Sự kết hợp giữa quy mô sản xuất lớn và tâm huyết của hàng ngàn nông dân giúp mỗi sản phẩm đạt được cấu trúc hài hòa, hương vị phong phú nhưng vẫn giữ mức giá đầy cạnh tranh.\r\n\r\nTại RUOUCHAT.vn, chúng tôi tuyển chọn những chai vang tiêu biểu nhất từ Caviro để đáp ứng đa dạng nhu cầu, từ thưởng thức hàng ngày đến phục vụ tiệc cao cấp. Dòng sản phẩm này không chỉ đại diện cho phong cách làm vang Ý truyền thống mà còn là minh chứng cho sự tối ưu hóa kỹ thuật trong ngành công nghiệp đồ uống toàn cầu. Đội ngũ chuyên gia tại RUOUCHAT.vn sẵn sàng cung cấp các thông tin chi tiết về đặc điểm vùng trồng (appellation) và gợi ý kết hợp ẩm thực để tối ưu trải nghiệm thưởng thức vang của quý khách hàng.', '', '', NULL, '', 0, 1, 1),
(58, 'Collefrisio', 'collefrisio', 50, 1, '<h1 data-path-to-node=\"8\" class=\"\" style=\"text-align: center; \">Rượu Vang Collefrisio</h1><p style=\"text-align: justify;\"><span style=\"text-align: start;\">Lựa chọn một chai rượu vang nhập khẩu cao cấp không đơn thuần là tìm kiếm một đồ uống cho bữa tiệc, mà còn là hành trình trải nghiệm nét đẹp văn hóa, thổ nhưỡng và tâm huyết của nhà làm vang. Tuy nhiên, giữa muôn vàn sự lựa chọn trên thị trường, nhiều người hâm mộ vang Ý thường gặp khó khăn trong việc tìm kiếm những chai vang vừa giữ được cá tính truyền thống của vùng đất bản địa, vừa sở hữu thiết kế sang trọng, hiện đại để làm quà biếu tặng hoặc thưởng thức trong các dịp trọng đại.</span></p><p data-path-to-node=\"10\" style=\"text-align: left;\">Nếu bạn đang tìm kiếm sự giao thoa hoàn hảo đó từ vùng đất <b data-path-to-node=\"10\" data-index-in-node=\"59\">Abruzzo</b> – cái nôi của giống nho Montepulciano lừng danh – <b data-path-to-node=\"10\" data-index-in-node=\"117\">Collefrisio</b> chính là câu trả lời xứng đáng nhất. Tại <b data-path-to-node=\"10\" data-index-in-node=\"170\">Ruouchat.vn</b>, chúng tôi mang đến bộ sưu tập rượu vang Collefrisio nhập khẩu chính hãng, đầy đủ giấy tờ chứng nhận xuất xứ, cam kết bảo quản chuẩn hầm rượu để mang tới hương vị trọn vẹn nhất cho quý khách.</p>', 'Rượu Vang Collefrisio Chính Hãng từ Abruzzo', 'Khám phá rượu vang Collefrisio chính hãng từ Abruzzo, Ý tại Ruouchat.vn. Hương vị đậm đà, tư vấn chuẩn chuyên gia, giao hàng toàn quốc. Xem ngay', NULL, 'uploads/producers/1784002595_6a55b82361e78.png', 0, 1, 1),
(59, 'GlenAllachie', 'glenallachie', 50, 1, 'GlenAllachie là biểu tượng của nghệ thuật làm Whisky tại Speyside, nổi bật với quy trình ủ rượu tỉ mỉ trong các loại thùng gỗ sồi tuyển chọn, tạo nên cấu trúc hương vị vô cùng phức hợp. Dưới sự dẫn dắt của bậc thầy chưng cất Billy Walker, GlenAllachie mang đến những dòng Single Malt có tầng hương đặc trưng của mật ong, gia vị ấm nồng và trái cây sấy đậm đà, phản ánh trung thực bản sắc vùng Terroir độc bản. Tại RUOUCHAT.vn, chúng tôi thấu hiểu giá trị của từng niên vụ, do đó mỗi chai GlenAllachie đều được kiểm định khắt khe về thông số kỹ thuật và điều kiện bảo quản.\r\n\r\nChúng tôi cung cấp dữ liệu chuyên sâu về độ tuổi (aging), loại thùng ủ và đặc tính hương vị, giúp giới mộ điệu dễ dàng nắm bắt sự tinh túy trong từng giọt rượu. RUOUCHAT.vn không chỉ cung cấp sản phẩm mà còn khẳng định vị thế dẫn đầu trong việc định hình trải nghiệm thưởng thức Whisky đẳng cấp tại thị trường Việt Nam. Mỗi chai rượu khi đến tay khách hàng đều giữ trọn vẹn đặc tính nguyên bản từ nhà chưng cất, đáp ứng yêu cầu khắt khe nhất của các nhà sưu tầm. Hãy khám phá ngay bộ sưu tập GlenAllachie tại website để nâng tầm trải nghiệm thưởng thức với tiêu chuẩn chất lượng cao cấp nhất.', '', '', NULL, '', 0, 1, 1),
(60, 'Tamdhu', 'tamdhu', 50, 1, 'Tamdhu là đại diện tiêu biểu cho phong cách Speyside cổ điển, nổi danh với triết lý sử dụng 100% thùng gỗ sồi Sherry Oloroso để chưng cất, tạo nên sắc màu tự nhiên sâu đậm cùng cấu trúc hương vị đặc trưng. Quá trình lão hóa kéo dài trong những thùng Sherry thượng hạng mang đến cho Tamdhu các tầng hương phức hợp của trái cây khô, gia vị ấm nồng và socola đen, phản ánh trung thực bản sắc vùng Terroir màu mỡ của Scotland. Tại RUOUCHAT.vn, chúng tôi thấu hiểu giá trị của di sản này nên luôn ưu tiên các phiên bản giới hạn, đảm bảo thông số kỹ thuật chuẩn xác về độ tuổi (aging) và phương pháp ủ.\r\n\r\nViệc sở hữu một chai Tamdhu không chỉ là thưởng thức nghệ thuật chưng cất đỉnh cao mà còn là sự thấu hiểu về sự kiên định trong việc bảo tồn chất lượng truyền thống. Đội ngũ RUOUCHAT.vn cam kết cung cấp dữ liệu minh bạch, giúp giới mộ điệu cảm nhận trọn vẹn sự tinh túy từ mỗi giọt rượu khi thưởng thức tại gia. Mỗi sản phẩm được bảo quản trong môi trường tối ưu, giữ nguyên vẹn giá trị cốt lõi từ nhà chưng cất danh tiếng đến tay khách hàng. Hãy khám phá ngay bộ sưu tập Tamdhu tại RUOUCHAT.vn để khẳng định đẳng cấp và gu thưởng thức vang tầm cỡ của riêng bạn.\n[FEATURED:1]', '', '', NULL, '', 0, 1, 1),
(61, 'Cognac Lheraud', 'cognac-lheraud', 50, 1, 'Pháp\r\nCognac Lheraud là hiện thân của nghệ thuật chưng cất thủ công vùng Petite Champagne, nơi gia tộc Lheraud duy trì triết lý sản xuất không pha trộn và không phụ gia. Mỗi chai rượu đều là kết quả của sự kiên nhẫn trong các thùng gỗ sồi cổ xưa, mang đến cấu trúc hương vị đặc thù của trái cây sấy, mật ong rừng và các nốt gia vị quý hiếm. Tại RUOUCHAT.vn, chúng tôi tự hào mang đến những phiên bản Cognac Lheraud Vintage hiếm có, nơi mà thời gian và terroir được cô đọng trong từng giọt rượu, đáp ứng sự mong đợi của những nhà sưu tầm khắt khe nhất.\r\n\r\nVới nền tảng dữ liệu kỹ thuật minh bạch, RUOUCHAT.vn giúp quý khách hàng thấu hiểu sâu sắc giá trị của từng niên vụ, từ phương pháp chưng cất nồi tĩnh truyền thống đến quy trình đóng chai chuẩn mực. Mỗi sản phẩm khi đến tay khách hàng đều được cam kết bảo quản trong điều kiện lý tưởng, giữ trọn vẹn bản sắc nguyên bản và sự sang trọng vốn có của thương hiệu Lheraud danh tiếng. Hãy khám phá ngay bộ sưu tập tại website để nâng tầm trải nghiệm thưởng thức, khẳng định gu thẩm mỹ tinh tế và niềm đam mê với di sản rượu mạnh Pháp đích thực.', '', '', NULL, '', 0, 1, 1),
(70, 'Blend', 'blend', 46, 1, '', 'Rượu vang từ giống nho Blend', 'Rượu vang từ giống nho Blend', NULL, '', 0, 1, 0),
(71, 'Anthonij Rupert', 'anthonij-rupert', 50, 1, '<h1>Rượu Vang&nbsp;Anthonij Rupert</h1><p><b>Anthonij Rupert</b>\r\n  là biểu tượng vang cao cấp hàng đầu Nam Phi, bắt nguồn từ thung lũng huyền thoại\r\n  <b>Franschhoek</b>\r\n  thuộc vùng làm vang Franschhoek Valley. Với triết lý tôn vinh đặc tính Terroir đa dạng của từng vùng trồng nho riêng\r\n  biệt (\r\n  <i>single vineyard</i>\r\n  ), nhà làm vang danh tiếng này kết hợp hoàn hảo các giống nho Bordeaux cổ điển như\r\n  <b>Cabernet Sauvignon, Cabernet Franc, Merlot</b>\r\n  và\r\n  <b>Petit Verdot</b>\r\n  . Rượu sở hữu cấu trúc đậm đà (full-bodied), tầng hương phức hợp của quả mọng đen, mận chín, cacao hòa quyện cùng gỗ\r\n  sồi Pháp trưởng thành mịn màng, mang lại hậu vị vô cùng quyến rũ và bền bỉ.</p>\r\n<p>\r\n  Tại\r\n  <b>RUOUCHAT.vn</b>\r\n  , mỗi chai vang Anthonij Rupert đều được nhập khẩu chính ngạch và bảo quản trong hệ thống kho lạnh chuyên dụng tiêu\r\n  chuẩn Cellar để giữ trọn vẹn hương vị nguyên bản.\r\n  <b>RUOUCHAT.vn</b>\r\n  tự hào mang đến cho giới thưởng thức Việt Nam bộ sưu tập Anthonij Rupert thượng hạng, đáp ứng trọn vẹn cả nhu cầu\r\n  thưởng thức lẫn biếu tặng cao cấp.\r\n</p>', 'Rượu Vang Anthonij Rupert Cao Cấp Chính Hãng | RUOUCHAT.vn', 'Khám phá Anthonij Rupert – dòng vang Nam Phi đẳng cấp từ Franschhoek. RUOUCHAT.vn phân phối rượu vang Anthonij Rupert chính hãng, chuẩn vị Terroir thượng hạng!', NULL, '', 0, 1, 1);
INSERT INTO `categories` (`id`, `name`, `slug`, `parent_id`, `level`, `description`, `seo_title`, `seo_description`, `meta_description`, `image`, `order_position`, `status`, `is_producer`) VALUES
(72, 'Barramundi', 'barramundi', 50, 1, '<h1 data-path-to-node=\"7\">Rượu Vang Barramundi</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Barramundi</b> là thương hiệu vang Úc đầy phá cách và hiện đại, đại diện cho tinh thần phóng khoáng của vùng làm vang trù phú <b data-path-to-node=\"8\" data-index-in-node=\"122\">Murray Darling</b>. Sở hữu các dòng sản phẩm đa dạng từ giống nho đỏ đình đám như <b data-path-to-node=\"8\" data-index-in-node=\"200\">Shiraz, Cabernet Sauvignon</b> đến các giống nho trắng thanh lịch như <b data-path-to-node=\"8\" data-index-in-node=\"266\">Chardonnay, Sauvignon Blanc</b>, Barramundi gây ấn tượng mạnh bởi chất vang mượt mà, bùng nổ hương trái cây nhiệt đới chín mọng, thoảng nốt hương gỗ sồi tinh tế cùng độ chua cân bằng sảng khoái.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập vang Barramundi Úc, đảm bảo quy trình bảo quản nhiệt độ Cellar khắt khe để giữ nguyên trọn vẹn vị tươi mới nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"197\">RUOUCHAT.vn</b> đồng hành cùng bạn trên hành trình khám phá những dòng vang uống hàng ngày (daily-wine) chất lượng vượt trội, phù hợp cho mọi bữa tiệc và phong cách ẩm thực hiện đại.</p>', 'Rượu Vang Barramundi Úc Chính Hãng | RUOUCHAT.vn', 'Khám phá vang Barramundi Úc tươi mát, hiện đại. RUOUCHAT.vn phân phối rượu vang Barramundi chính hãng, giá tốt nhất với hương vị chuẩn Terroir Murray Darling!', NULL, '', 0, 1, 1),
(73, 'Batasiolo', 'batasiolo', 50, 1, '<h1 data-path-to-node=\"7\" style=\"text-align: center; \">Rượu Vang Batasiolo</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Beni di Batasiolo</b> là một trong những nhà sản xuất vang gia đình lớn nhất và danh tiếng nhất tại vùng <b data-path-to-node=\"8\" data-index-in-node=\"101\">Piedmont (Bắc Ý)</b>, thuộc sở hữu của gia tộc Dogliani. Tọa lạc tại trái tim của vùng <b data-path-to-node=\"8\" data-index-in-node=\"184\">Langhe DOC</b>, Batasiolo nổi tiếng thế giới nhờ việc sở hữu những vườn nho Barolo kiệt xuất trên các đồi đá vôi giàu khoáng chất. Các dòng vang của Batasiolo – đặc biệt là <b data-path-to-node=\"8\" data-index-in-node=\"353\">Barolo DOCG</b> làm từ giống nho <b data-path-to-node=\"8\" data-index-in-node=\"382\">Nebbiolo</b> – gây ấn tượng mạnh bởi sắc đỏ ruby đậm sâu, tầng hương phức hợp của hoa hồng khô, anh đào đen, cam thảo, nấm truffle cùng chất tannin mạnh mẽ, thanh lịch và khả năng lưu trữ vượt thời gian.</p><p data-path-to-node=\"9\">Các sản phẩm đỉnh cao của Batasiolo – tiêu biểu là dòng <b data-path-to-node=\"9\" data-index-in-node=\"56\">Barolo DOCG</b> – luôn ghi dấu ấn mạnh mẽ nhờ cấu trúc đậm đà, tầng hương phức hợp của hoa hồng khô, anh đào đen, nấm truffle cùng chất tannin mịn màng, mạnh mẽ và khả năng lão hóa tiềm năng trong hàng thập kỷ. Bên cạnh đó, các dòng vang trắng như <b data-path-to-node=\"9\" data-index-in-node=\"300\">Gavi di Gavi</b> (nho Cortese) hay vang sủi <b data-path-to-node=\"9\" data-index-in-node=\"340\">Moscato d\'Asti</b> cũng thể hiện trọn vẹn sự tươi mát, thanh lịch chuẩn phong cách Ý. Đồng hành cùng niềm đam mê thưởng thức vang hảo hạng, <b data-path-to-node=\"9\" data-index-in-node=\"476\">RUOUCHAT.vn</b> tự hào phân phối chính ngạch trọn bộ sưu tập vang Batasiolo được bảo quản chuẩn nhiệt độ Cellar khắt khe, mang đến giá trị nguyên bản nhất cho từng tín đồ vang Việt.</p>', 'Rượu Vang Batasiolo Ý Chính Hãng | RUOUCHAT.vn', 'Khám phá Batasiolo – gia tộc vang danh tiếng xứ Piedmont. RUOUCHAT.vn phân phối rượu vang Batasiolo chính hãng, chuẩn vị Barolo đẳng cấp!', NULL, 'uploads/category/20260804_151303_6a719f0fe7fd6.jpg', 0, 1, 1),
(74, 'Beau Jardin', 'beau-jardin', 50, 1, '<h1 data-path-to-node=\"7\">Rượu Vang Beau Jardin</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Beau Jardin</b> là dòng rượu vang Pháp đại diện cho sự thanh lịch và phóng khoáng, phản ánh trọn vẹn nét đặc trưng của những khu vườn nho thơ mộng tại miền Nam nước Pháp. Được phối trộn khéo léo từ các giống nho phổ biến như <b data-path-to-node=\"8\" data-index-in-node=\"221\">Cabernet Sauvignon, Merlot</b> đối với vang đỏ hay <b data-path-to-node=\"8\" data-index-in-node=\"268\">Chardonnay, Sauvignon Blanc</b> đối với vang trắng, Beau Jardin mang đến hương vị tròn trịa, nổi bật với nốt hương trái cây tươi mọng như mâm xôi, anh đào cùng chút gia vị nhẹ nhàng. Cấu trúc cân bằng, chất tannin mượt mà và hậu vị sảng khoái biến Beau Jardin trở thành lựa chọn tuyệt vời cho các bữa ăn hàng ngày cũng như những buổi tiệc nhẹ nhàng.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi phân phối chính ngạch các sản phẩm vang Beau Jardin với đầy đủ chứng nhận nguồn gốc xuất xứ. Mọi chai vang đều được lưu giữ trong hệ thống kho lạnh tiêu chuẩn Cellar khắt khe nhằm bảo đảm cấu trúc nguyên bản và độ tươi ngon nhất. <b data-path-to-node=\"9\" data-index-in-node=\"257\">RUOUCHAT.vn</b> luôn là điểm đến đáng tin cậy giúp bạn sở hữu những dòng vang chất lượng chuẩn gu với mức giá tối ưu nhất.</p>', 'Rượu Vang Beau Jardin Pháp Chính Hãng | RUOUCHAT.vn', 'Khám phá Beau Jardin – dòng vang Pháp thanh lịch, thơm ngon. Mua ngay rượu vang Beau Jardin chính hãng, chuẩn vị Terroir với giá tốt nhất tại RUOUCHAT.vn!', NULL, '', 0, 1, 1),
(75, 'Beaumont Des Crayères', 'beaumont-des-crayeres', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\">Rượu Vang Beaumont Des Crayères</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Beaumont Des Crayères</b> là thương hiệu Champagne danh tiếng xuất xứ từ vùng <b data-path-to-node=\"8\" data-index-in-node=\"74\">Mardeuil (Đồng bằng Épernay, Champagne, Pháp)</b>, nổi tiếng với kỹ nghệ làm sủi bọt tỉ mỉ từ sự kết hợp xuất sắc của ba giống nho <b data-path-to-node=\"8\" data-index-in-node=\"201\">Meunier, Chardonnay và Pinot Noir</b>. Được nuôi dưỡng trên thổ nhưỡng đất đá vôi (<i data-path-to-node=\"8\" data-index-in-node=\"280\">Crayères</i>) đặc trưng giàu khoáng chất, nhà làm vang này mang đến những dòng Champagne có dải bọt sủi mịn màng, lan tỏa hương thơm tinh tế của trái cây đá, hoa trắng cùng nốt bánh mì nướng (<i data-path-to-node=\"8\" data-index-in-node=\"468\">Brioche</i>) béo ngậy. Cấu trúc vang thanh lịch, độ chua (<i data-path-to-node=\"8\" data-index-in-node=\"522\">Acidity</i>) sống động và hậu vị khoáng đạt kéo dài chính là dấu ấn Terroir khác biệt giúp Beaumont Des Crayères chinh phục giới mộ điệu toàn cầu.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, mỗi chai Champagne Beaumont Des Crayères đều được nhập khẩu chính ngạch và lưu giữ khắt khe trong kho lạnh tiêu chuẩn Cellar nhằm duy trì áp suất bọt cùng hương vị nguyên bản nhất. <b data-path-to-node=\"9\" data-index-in-node=\"198\">RUOUCHAT.vn</b> tự hào phân phối bộ sưu tập Beaumont Des Crayères thượng hạng, là lựa chọn hoàn hảo cho những dịp khai vị sang trọng, tiệc ăn mừng cũng như quà tặng doanh nghiệp đẳng cấp.</p>', 'Champagne Beaumont Des Crayères Chính Hãng | RUOUCHAT.vn', 'Khám phá Champagne Beaumont Des Crayères cao cấp từ Bồ Đào Nha/Pháp. Mua ngay Champagne Beaumont chính hãng, chuẩn Terroir Mardeuil tại RUOUCHAT.vn!', NULL, '', 0, 1, 1),
(76, 'Bernard Magrez', 'bernard-magrez', 50, 1, '<h1 data-path-to-node=\"7\">Rượu Vang Bernard Magrez</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Bernard Magrez</b> là huyền thoại làm vang hàng đầu nước Pháp, người duy nhất sở hữu tới 4 điền trang đạt cấp độ <b data-path-to-node=\"8\" data-index-in-node=\"109\">Grand Cru Classé</b> tại các vùng đất vàng Bordeaux bao gồm <i data-path-to-node=\"8\" data-index-in-node=\"165\">Château Pape Clément (Pessac-Léognan)</i>, <i data-path-to-node=\"8\" data-index-in-node=\"204\">Château La Tour Carnet (Haut-Médoc)</i>, <i data-path-to-node=\"8\" data-index-in-node=\"241\">Château Fombrauge (Saint-Émilion)</i> và <i data-path-to-node=\"8\" data-index-in-node=\"278\">Clos Haut-Peyraguey (Sauternes)</i>. Mang trong mình triết lý theo đuổi sự hoàn hảo vượt trội, các dòng vang mang dấu ấn hình chìa khóa chéo của Bernard Magrez thể hiện sự kết hợp tinh tế giữa nghệ thuật phối trộn truyền thống từ <b data-path-to-node=\"8\" data-index-in-node=\"504\">Cabernet Sauvignon, Merlot</b> và kỹ thuật ủ gỗ sồi Pháp tân tiến. Vang sở hữu màu sắc đậm đà, cấu trúc đầy đặn (full-bodied), tầng hương phức hợp của mứt quả mọng, cacao, gia vị ấm cùng chất tannin mượt mà, sâu lắng.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi tự hào mang đến cho giới thưởng thức Việt Nam bộ sưu tập vang Bernard Magrez chính hãng được nhập khẩu nguyên chai trực tiếp. Mọi sản phẩm đều trải qua quy trình lưu kho khắt khe ở nhiệt độ tiêu chuẩn Cellar nhằm duy trì tiềm năng lão hóa tuyệt vời và trọn vẹn giá trị Terroir kiệt xuất. <b data-path-to-node=\"9\" data-index-in-node=\"315\">RUOUCHAT.vn</b> chính là bảo chứng uy tín cho những trải nghiệm thưởng thức đẳng cấp và biếu tặng thượng lưu.</p>', 'Rượu Vang Bernard Magrez Pháp Chính Hãng | RUOUCHAT.vn', 'Khám phá Bernard Magrez – đế chế vang Bordeaux đẳng cấp. RUOUCHAT.vn phân phối rượu vang Bernard Magrez chính hãng, chuẩn vị Terroir Grand Cru Classé!', NULL, '', 0, 1, 1),
(78, 'Muga', 'muga', 50, 1, '<h1 data-path-to-node=\"7\">Rượu Vang Muga</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Bodegas Muga</b> là nhà sản xuất rượu vang gia đình danh tiếng bậc nhất vùng <b data-path-to-node=\"8\" data-index-in-node=\"73\">Rioja Alta (Tây Ban Nha)</b>, nổi tiếng thế giới nhờ duy trì xưởng đóng thùng gỗ sồi riêng (<i data-path-to-node=\"8\" data-index-in-node=\"161\">cooperage</i>) để kiểm soát tuyệt đối quá trình lão hóa. Được chế tác từ các giống nho bản địa ưu tú như <b data-path-to-node=\"8\" data-index-in-node=\"262\">Tempranillo, Garnacha, Mazuelo</b> và <b data-path-to-node=\"8\" data-index-in-node=\"296\">Graciano</b>, vang Muga thể hiện trọn vẹn nét đẹp cổ điển phối hợp hoàn hảo với tư duy hiện đại. Rượu sở hữu sắc đỏ ruby thẫm, bung tỏa tầng hương phức hợp của quả mọng đen, da thuộc, vani, cacao cùng chút gia vị ấm áp. Cấu trúc vang full-bodied đậm đà, chất tannin mịn như lụa và độ chua tự nhiên cân bằng mang lại hậu vị sâu lắng, giàu tiềm năng lưu trữ qua nhiều năm.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập Muga từ <i data-path-to-node=\"9\" data-index-in-node=\"86\">Muga Reserva, Gran Reserva</i> cho tới các dòng biểu tượng (<i data-path-to-node=\"9\" data-index-in-node=\"142\">Icon Wine</i>) như <i data-path-to-node=\"9\" data-index-in-node=\"157\">Aro</i> và <i data-path-to-node=\"9\" data-index-in-node=\"164\">Prado Enea</i>. Toàn bộ sản phẩm được bảo quản khắt khe trong kho lạnh tiêu chuẩn Cellar nhằm duy trì hương vị nguyên bản và cấu trúc tinh tế nhất. <b data-path-to-node=\"9\" data-index-in-node=\"308\">RUOUCHAT.vn</b> tự hào là điểm đến uy tín đồng hành cùng những tín đồ sành vang trên hành trình thưởng thức nghệ thuật vang Rioja đích thực.</p>', 'Rượu Vang Muga Rioja Tây Ban Nha | RUOUCHAT.vn', 'Khám phá Muga – biểu tượng vang Rioja Tây Ban Nha. RUOUCHAT.vn phân phối rượu vang Muga chính hãng, chuẩn vị Terroir Haro, ủ gỗ sồi thủ công!', NULL, '', 0, 1, 1),
(79, 'San Marzano', 'san-marzano', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\">Rượu Vang San Marzano</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Cantine San Marzano</b> là nhà sản xuất rượu vang biểu tượng được thành lập từ năm 1962 tại trái tim bán đảo Salento, thuộc vùng <b data-path-to-node=\"8\" data-index-in-node=\"125\">Puglia (Nam Ý)</b>. Thương hiệu nổi tiếng toàn cầu nhờ việc khai thác xuất sắc những gốc nho cổ thụ (<i data-path-to-node=\"8\" data-index-in-node=\"222\">Old Vines / Vigneti del Salento</i>) kết hợp với chất đất đỏ chứa nhiều sắt và đá vôi đặc trưng. Sử dụng hai giống nho bản địa chủ đạo là <b data-path-to-node=\"8\" data-index-in-node=\"356\">Primitivo</b> và <b data-path-to-node=\"8\" data-index-in-node=\"369\">Negroamaro</b>, vang San Marzano chinh phục người thưởng thức bởi cấu trúc đậm đà (full-bodied), nồng độ cồn tròn trịa, bung tỏa tầng hương mượt mà của mận chín, mứt quả mọng, cacao và gia vị ấm từ quá trình ủ thùng gỗ sồi Pháp &amp; Mỹ.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi mang đến bộ sưu tập San Marzano chính hãng phong phú từ các dòng vang uống hàng ngày đến những tuyệt tác huyền thoại như <i data-path-to-node=\"9\" data-index-in-node=\"148\">F Gold Series</i>, <i data-path-to-node=\"9\" data-index-in-node=\"163\">Sessantanni Primitivo di Manduria DOP</i>. Toàn bộ sản phẩm được nhập khẩu nguyên chai, bảo quản khắt khe trong kho lạnh tiêu chuẩn Cellar để giữ trọn vẹn hương vị nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"335\">RUOUCHAT.vn</b> tự hào là điểm đến uy tín giúp quý khách hàng trải nghiệm đỉnh cao nghệ thuật vang Nam Ý với dịch vụ và chất lượng chuẩn mực nhất.</p>', 'Rượu Vang San Marzano Ý Chính Hãng | RUOUCHAT.vn', 'Khám phá San Marzano – thương hiệu vang Ý lừng danh xứ Puglia. RUOUCHAT.vn phân phối rượu vang San Marzano chính hãng, chuẩn vị Terroir Salento cao cấp!', NULL, '', 0, 1, 1),
(80, 'Luccarelli', 'luccarelli', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\">Rượu Vang Luccarelli</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Luccarelli</b> là thương hiệu vang Ý danh tiếng thuộc tập đoàn <b data-path-to-node=\"8\" data-index-in-node=\"59\">Farnese Fantini</b>, đại diện cho phong cách làm vang hiện đại và đậm đà của vùng đất nắng gió <b data-path-to-node=\"8\" data-index-in-node=\"150\">Puglia (Nam Ý)</b>. Sử dụng kỹ thuật ép nho nhẹ nhàng kết hợp kiểm soát nhiệt độ lên men nghiêm ngặt, Luccarelli khai thác tối đa tiềm năng của các giống nho bản địa kinh điển như <b data-path-to-node=\"8\" data-index-in-node=\"326\">Primitivo, Negroamaro</b> và <b data-path-to-node=\"8\" data-index-in-node=\"351\">Malvasia Nera</b>. Vang sở hữu màu đỏ ruby ánh tím bắt mắt, bung tỏa tầng hương thơm nồng nàn của quả mọng đen chín mọng, mứt mận, cam thảo hòa quyện cùng nốt hương gia vị ấm áp, chất tannin mượt mà và hậu vị êm ái, sâu lắng.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, các sản phẩm vang Luccarelli – tiêu biểu như dòng <i data-path-to-node=\"9\" data-index-in-node=\"67\">Luccarelli Primitivo Puglia IGP</i> – đều được nhập khẩu nguyên chai chính ngạch và bảo quản trong hệ thống kho lạnh chuẩn nhiệt độ Cellar khắt khe. <b data-path-to-node=\"9\" data-index-in-node=\"212\">RUOUCHAT.vn</b> tự hào mang đến cho quý khách hàng những trải nghiệm vang Nam Ý chuẩn vị Terroir với mức giá tối ưu cùng dịch vụ tư vấn chuyên nghiệp nhất.</p>', 'Rượu Vang Luccarelli Ý Chính Hãng | RUOUCHAT.vn', 'Khám phá vang Luccarelli Ý đậm đà chuẩn vị Puglia. RUOUCHAT.vn phân phối rượu vang Luccarelli chính hãng, giá tốt nhất với ưu đãi hấp dẫn!', NULL, '', 0, 1, 1),
(81, 'Fantini', 'fantini', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\">Rượu Vang Fantini</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Fantini</b> (thuộc Fantini Group, tiền thân là Farnese Vini) là thương hiệu vang Ý biểu tượng, đại diện cho đỉnh cao nghệ thuật làm vang hiện đại tại miền Trung và Nam Ý như <b data-path-to-node=\"8\" data-index-in-node=\"170\">Abruzzo, Puglia</b> và <b data-path-to-node=\"8\" data-index-in-node=\"189\">Basilicata</b>. Nhờ triết lý khai thác những gốc nho cổ thụ (<i data-path-to-node=\"8\" data-index-in-node=\"246\">Old Vines</i>) trên thổ nhưỡng đất sét đá vôi giàu khoáng chất, Fantini nâng tầm các giống nho bản địa kinh điển như <b data-path-to-node=\"8\" data-index-in-node=\"359\">Montepulciano, Primitivo, Sangiovese</b> và <b data-path-to-node=\"8\" data-index-in-node=\"399\">Pecorino</b>. Rượu ghi dấu ấn mạnh mẽ với màu sắc đậm đà, tầng hương phức hợp của quả mọng đen chín cất, mứt mận, cacao cùng chút gia vị ấm áp từ gỗ sồi. Cấu trúc vang đậm tròn (full-bodied), chất tannin mượt như lụa và hậu vị sâu lắng đã giúp Fantini liên tục nhận danh hiệu \"Nhà sản xuất vang tốt nhất nước Ý\" từ các tạp chí uy tín.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch bộ sưu tập Fantini phong phú, từ các dòng uống hàng ngày chất lượng đến những tuyệt tác huyền thoại như <i data-path-to-node=\"9\" data-index-in-node=\"166\">Edizione Cinque Autoctoni</i>. Mọi sản phẩm đều được lưu giữ trong hệ thống kho lạnh tiêu chuẩn Cellar khắt khe nhằm đảm bảo cấu trúc và hương vị nguyên bản nhất. <b data-path-to-node=\"9\" data-index-in-node=\"325\">RUOUCHAT.vn</b> tự hào là điểm đến uy tín đồng hành cùng các tín đồ sành vang trên hành trình thưởng thức phong vị nước Ý đích thực.</p>', 'Rượu Vang Fantini Ý Chính Hãng | RUOUCHAT.vn', 'Khám phá vang Fantini Ý đậm đà từ Fantini Group. RUOUCHAT.vn phân phối rượu vang Fantini chính hãng, giá tốt nhất với vị Terroir Puglia & Abruzzo!', NULL, 'uploads/category/20260804_141201_6a7190c1e1a8c.jpg', 0, 1, 1),
(82, 'Castello ColleMassari', 'castello-collemassari', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\">Rượu Vang Castello ColleMassari</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Castello ColleMassari</b> là điền trang vang hữu cơ (Organic) biểu tượng tọa lạc tại vùng <b data-path-to-node=\"8\" data-index-in-node=\"86\">Montecucco DOC/DOCG</b>, thuộc vùng Tuscany (Ý). Nằm ở độ cao hoàn hảo trên các sườn đồi đón gió biển Tyrrhenian, ColleMassari nổi tiếng thế giới với việc nâng tầm giống nho bản địa <b data-path-to-node=\"8\" data-index-in-node=\"264\">Sangiovese</b> cùng các giống nho phối trộn thanh lịch như <b data-path-to-node=\"8\" data-index-in-node=\"319\">Ciliegiolo, Montepulciano</b> và <b data-path-to-node=\"8\" data-index-in-node=\"348\">Vermentino</b>. Vang sở hữu màu đỏ ruby sâu lắng, bung tỏa hương thơm tươi mới của anh đào dại, mận chín, thảo mộc địa trung hải cùng nốt hương khoáng chất đặc trưng. Cấu trúc vang cân bằng tinh tế, chất tannin mịn màng, độ chua sống động mang đến trải nghiệm thưởng thức vừa phóng khoáng vừa sâu lắng.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch các dòng vang Castello ColleMassari thượng hạng với đầy đủ chứng nhận nguồn gốc và tiêu chuẩn hữu cơ. Mọi chai vang đều được bảo quản khắt khe trong kho lạnh chuyên dụng chuẩn Cellar nhằm duy trì sự tươi ngon và hương vị nguyên bản nhất. <b data-path-to-node=\"9\" data-index-in-node=\"300\">RUOUCHAT.vn</b> tự hào là điểm đến tin cậy đồng hành cùng tín đồ sành vang trên hành trình khám phá những giá trị Terroir Tuscan đích thực.</p>', 'Rượu Vang Castello ColleMassari Chính Hãng | RUOUCHAT.vn', 'Khám phá Castello ColleMassari – tuyệt tác vang hữu cơ Montecucco Ý. RUOUCHAT.vn phân phối vang ColleMassari chính hãng, chuẩn vị Terroir Tuscan!', NULL, 'uploads/category/20260804_141410_6a719142dfa66.jpg', 0, 1, 1);
INSERT INTO `categories` (`id`, `name`, `slug`, `parent_id`, `level`, `description`, `seo_title`, `seo_description`, `meta_description`, `image`, `order_position`, `status`, `is_producer`) VALUES
(83, 'Tenuta Perano', 'tenuta-perano', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\">Rượu Vang Tenuta Perano</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Tenuta Perano</b> là điền trang kiệt xuất thuộc tập đoàn vang huyền thoại <b data-path-to-node=\"8\" data-index-in-node=\"70\">Frescobaldi</b>, tọa落 tại trái tim <b data-path-to-node=\"8\" data-index-in-node=\"101\">Gaiole in Chianti</b> – vùng đất vàng của tiểu vùng <b data-path-to-node=\"8\" data-index-in-node=\"149\">Chianti Classico (Tuscany, Ý)</b>. Nằm ở độ cao 500m so với mực nước biển với địa hình lòng chảo tự nhiên đón trọn ánh nắng mặt trời, Tenuta Perano sở hữu điều kiện thổ nhưỡng đá vôi <i data-path-to-node=\"8\" data-index-in-node=\"328\">Galestro</i> lý tưởng để phát triển giống nho <b data-path-to-node=\"8\" data-index-in-node=\"370\">Sangiovese</b> chuẩn mực. Sự kết hợp giữa biên độ nhiệt ngày đêm lớn cùng kỹ thuật ủ gỗ sồi Pháp tỉ mỉ giúp vang Tenuta Perano sở hữu sắc đỏ ruby lộng lẫy, bung tỏa hương thơm phức hợp của quả anh đào dại, hoa violet, cam thảo, thảo mộc địa trung hải cùng nốt hương khoáng chất sắc nét. Cấu trúc vang thanh lịch, chất tannin mịn màng, độ chua tự nhiên sống động mang lại hậu vị sâu lắng, trường tồn theo thời gian.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập Tenuta Perano từ dòng <i data-path-to-node=\"9\" data-index-in-node=\"100\">Chianti Classico DOCG</i> cho đến <i data-path-to-node=\"9\" data-index-in-node=\"130\">Chianti Classico Gran Selezione</i> cao cấp. Toàn bộ sản phẩm được lưu giữ trong hệ thống kho lạnh chuyên dụng chuẩn tiêu chuẩn Cellar khắt khe nhằm bảo toàn trọn vẹn cấu trúc và hương vị nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"326\">RUOUCHAT.vn</b> tự hào là cầu nối uy tín mang giá trị Terroir Tuscan đích thực và trải nghiệm thưởng thức đẳng cấp đến tay quý khách hàng.</p>', 'Rượu Vang Tenuta Perano Chianti Classico | RUOUCHAT.vn', 'Khám phá Tenuta Perano từ Frescobaldi – tuyệt tác Chianti Classico Ý. Mua vang Tenuta Perano chính hãng, giá tốt, chuẩn vị Terroir Gaiole tại RUOUCHAT.vn!', NULL, 'uploads/category/20260804_142153_6a719311ce2d8.png', 0, 1, 1),
(84, 'Nipozzano Castle', 'nipozzano-castle', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\">Rượu Vang Castello Nipozzano</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Castello Nipozzano</b> (Nipozzano Castle) là lâu đài kiệt xuất có lịch sử hơn 1.000 năm thuộc sở hữu của gia tộc vang huyền thoại <b data-path-to-node=\"8\" data-index-in-node=\"126\">Frescobaldi</b>, tọa lạc tại vùng <b data-path-to-node=\"8\" data-index-in-node=\"156\">Chianti Rùfina (Tuscany, Ý)</b>. Nhờ địa hình đồi núi đón gió sương cùng thổ nhưỡng đất sét - đá vôi giàu khoáng chất, Nipozzano là cái nôi sản xuất ra những dòng vang <b data-path-to-node=\"8\" data-index-in-node=\"320\">Sangiovese</b> chuẩn mực, kết hợp tinh tế cùng các giống nho Bordeaux như <b data-path-to-node=\"8\" data-index-in-node=\"390\">Cabernet Sauvignon, Merlot</b> và <b data-path-to-node=\"8\" data-index-in-node=\"420\">Petit Verdot</b>. Rượu mang sắc đỏ ruby sâu lộng lẫy, bung tỏa tầng hương phức hợp của quả anh đào dại, mận chín, hoa violet, cam thảo hòa quyện cùng nốt hương gia vị, gỗ sồi Pháp và khoáng chất sắc nét. Cấu trúc vang đậm đà, chất tannin mịn màng, độ chua tự nhiên sống động mang lại hậu vị sâu lắng, giàu tiềm năng lão hóa qua nhiều thập kỷ.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập từ lâu đài Nipozzano, tiêu biểu như dòng <i data-path-to-node=\"9\" data-index-in-node=\"119\">Nipozzano Riserva Chianti Rùfina DOCG</i> hay tuyệt tác <i data-path-to-node=\"9\" data-index-in-node=\"171\">Vecchie Viti</i>. Toàn bộ sản phẩm đều được lưu giữ khắt khe trong hệ thống kho lạnh chuyên dụng chuẩn nhiệt độ Cellar để bảo toàn trọn vẹn hương vị nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"328\">RUOUCHAT.vn</b> tự hào là cầu nối uy tín mang phong vị Terroir Tuscan thượng hạng cùng trải nghiệm thưởng thức đẳng cấp đến tay quý khách hàng.</p>', 'Rượu Vang Castello Nipozzano Chianti Classico | RUOUCHAT.vn', 'Khám phá Castello Nipozzano từ Frescobaldi – biểu tượng Chianti Rùfina Ý. Mua vang Nipozzano chính hãng, giá tốt, chuẩn vị Terroir Tuscan tại RUOUCHAT.vn!', NULL, 'uploads/category/20260804_142317_6a7193654f664.jpg', 0, 1, 1),
(85, 'Tenuta CastelGiocondo', 'tenuta-castelgiocondo', 50, 1, '<h1 class=\"\">Rượu Vang Tenuta CastelGiocondo</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Tenuta CastelGiocondo</b> là điền trang lịch sử lâu đời thuộc tập đoàn vang danh tiếng <b data-path-to-node=\"8\" data-index-in-node=\"83\">Frescobaldi</b>, tọa lạc tại độ cao lý tưởng của vùng <b data-path-to-node=\"8\" data-index-in-node=\"133\">Montalcino (Tuscany, Ý)</b>. Lâu đài cổ kính này là một trong những cái nôi đầu tiên khai sinh ra dòng vang biểu tượng <b data-path-to-node=\"8\" data-index-in-node=\"248\">Brunello di Montalcino DOCG</b> từ giống nho <b data-path-to-node=\"8\" data-index-in-node=\"289\">Sangiovese Grosso</b> (Brunello) thuần khiết. Nhờ sự kết hợp hoàn hảo giữa thổ nhưỡng đất đá vôi, đất sét giàu khoáng chất (<i data-path-to-node=\"8\" data-index-in-node=\"409\">Marl &amp; Galestro</i>) và kỹ thuật ủ lâu năm trong thùng gỗ sồi Slavonian &amp; Pháp, vang CastelGiocondo sở hữu màu đỏ ruby thẫm quý phái, bung tỏa tầng hương phức hợp của quả anh đào chín, mâm xôi, mứt mận hòa quyện cùng nốt hương da thuộc, thuốc lá, cacao và vani ấm áp. Cấu trúc vang vô cùng đậm đà (full-bodied), tannin tròn trịa, đặn dầy cùng độ chua sắc nét mang lại khả năng lưu trữ và phát triển hương vị qua hàng thập kỷ.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch các dòng vang CastelGiocondo thượng hạng bao gồm cả phiên bản <i data-path-to-node=\"9\" data-index-in-node=\"124\">Brunello di Montalcino</i> và <i data-path-to-node=\"9\" data-index-in-node=\"150\">Campo ai Sassi Rosso di Montalcino</i>. Mọi sản phẩm đều được lưu giữ nghiêm ngặt trong hệ thống kho lạnh đạt tiêu chuẩn Cellar khắt khe nhằm duy trì trọn vẹn giá trị Terroir nguyên bản cùng tiềm năng lão hóa đỉnh cao. <b data-path-to-node=\"9\" data-index-in-node=\"365\">RUOUCHAT.vn</b> tự hào là điểm đến tin cậy đồng hành cùng giới thưởng thức trên hành trình trải nghiệm những kiệt tác vang Ý chuẩn mực nhất.</p>', 'Rượu Vang Tenuta CastelGiocondo Chính Hãng | RUOUCHAT.vn', 'Khám phá Tenuta CastelGiocondo từ Frescobaldi – tuyệt tác Brunello di Montalcino Ý. Mua vang CastelGiocondo chính hãng, chuẩn vị Terroir tại RUOUCHAT.vn!', NULL, 'uploads/category/20260804_142521_6a7193e154839.jpg', 0, 1, 1),
(86, 'Marchesi Frescobaldi', 'marchesi-frescobaldi', 50, 1, '<p><h3 data-path-to-node=\"6\"></h3></p><h1 data-path-to-node=\"7\" class=\"\">Rượu Vang Marchesi Frescobaldi</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Marchesi Frescobaldi</b> là gia tộc làm vang huyền thoại với hơn 700 năm lịch sử, đại diện cho di sản và biểu tượng đỉnh cao của vùng <b data-path-to-node=\"8\" data-index-in-node=\"130\">Tuscany (Ý)</b>. Sở hữu các điền trang danh tiếng như <i data-path-to-node=\"8\" data-index-in-node=\"180\">Castello Nipozzano, Tenuta CastelGiocondo, Tenuta Perano</i> và <i data-path-to-node=\"8\" data-index-in-node=\"240\">Ornellaia</i>, Frescobaldi thể hiện trọn vẹn sự đa dạng của thổ nhưỡng đất đá vôi, đất sét <i data-path-to-node=\"8\" data-index-in-node=\"327\">Galestro</i> qua giống nho <b data-path-to-node=\"8\" data-index-in-node=\"350\">Sangiovese</b> chuẩn mực cùng các giống nho quốc tế <b data-path-to-node=\"8\" data-index-in-node=\"398\">Cabernet Sauvignon, Merlot</b>. Các dòng vang Frescobaldi nổi tiếng với sắc đỏ ruby sâu, bung tỏa tầng hương phức hợp của anh đào dại, mận chín, gia vị ấm, gỗ sồi Pháp và khoáng chất sắc nét. Cấu trúc vang đậm đà, tannin mượt mà cùng độ chua cân bằng mang lại tiềm năng lão hóa tuyệt vời.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập Marchesi Frescobaldi, lưu giữ khắt khe trong kho lạnh chuẩn nhiệt độ Cellar để bảo toàn nguyên vẹn cấu trúc và chất lượng nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"212\">RUOUCHAT.vn</b> tự hào là điểm đến uy tín đồng hành cùng quý khách trên hành trình khám phá những kiệt tác vang Ý thượng hạng.</p>', 'Rượu Vang Marchesi Frescobaldi Ý | RUOUCHAT.vn', 'Khám phá Marchesi Frescobaldi – gia tộc vang 700 năm lịch sử tại Tuscany Ý. Mua vang Frescobaldi chính hãng, chuẩn vị Terroir tại RUOUCHAT.vn!', NULL, 'uploads/category/20260804_143234_6a7195923eeff.jpg', 0, 1, 1),
(87, 'Tenuta Ammiraglia', 'tenuta-ammiraglia', 50, 1, '<h1 class=\"\">Rượu Vang Tenuta Ammiraglia</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Tenuta Ammiraglia</b> là điền trang hiện đại mang tính biểu tượng của gia tộc danh tiếng <b data-path-to-node=\"8\" data-index-in-node=\"85\">Frescobaldi</b>, tọa lạc tại vùng đất giàu tiềm năng <b data-path-to-node=\"8\" data-index-in-node=\"134\">Maremma (Tuscany, Ý)</b>. Nằm thoai thoải trên những ngọn đồi hướng ra biển Địa Trung Hải, Ammiraglia sở hữu điều kiện Terroir độc đáo với nắng ấm dồi dào, gió biển tươi mát cùng thổ nhưỡng đồi sỏi giàu khoáng chất. Điền trang nổi tiếng với việc kết hợp hoàn hảo giữa các giống nho quốc tế và bản địa như <b data-path-to-node=\"8\" data-index-in-node=\"435\">Syrah, Vermentino, Cabernet Sauvignon</b> và <b data-path-to-node=\"8\" data-index-in-node=\"476\">Sangiovese</b>, sáng tạo nên những dòng vang đậm đà, hiện đại nhưng vẫn giữ trọn bản sắc vùng biển Tuscany.</p><p data-path-to-node=\"9\">Các sản phẩm của Tenuta Ammiraglia – tiêu biểu như dòng vang hồng <i data-path-to-node=\"9\" data-index-in-node=\"66\">Alìe</i> hay vang đỏ <i data-path-to-node=\"9\" data-index-in-node=\"83\">Atea</i> – luôn chinh phục giới thưởng thức bởi sắc màu lộng lẫy, bung tỏa tầng hương thơm phong phú của trái cây mọng chín, hoa dại, thảo mộc khô cùng nốt khoáng mặn mòi quyến rũ. Chất vang tròn trịa, tannin mượt mà cùng độ chua cân bằng mang lại trải nghiệm thưởng thức vô cùng tươi mới, phóng khoáng. Tại <b data-path-to-node=\"9\" data-index-in-node=\"387\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu chính ngạch và bảo quản trọn bộ sưu tập Tenuta Ammiraglia trong hệ thống kho lạnh tiêu chuẩn Cellar khắt khe, cam kết mang đến giá trị trọn vẹn nhất cho quý khách hàng.</p>', 'Rượu Vang Tenuta Ammiraglia Ý | RUOUCHAT.vn', 'Khám phá Tenuta Ammiraglia từ Frescobaldi – làn gió biển Maremma Tuscany. Mua vang Tenuta Ammiraglia chính hãng, chuẩn vị Terroir tại RUOUCHAT.vn!', NULL, 'uploads/category/20260804_143603_6a71966339fbd.jpg', 0, 1, 1),
(88, 'Rèmole', 'remole', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\">Rượu Vang Rémole</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Rémole</b> là dòng rượu vang biểu tượng cho phong cách sống phóng khoáng và thanh lịch của nước Ý, được sáng tạo bởi gia tộc vang lừng danh <b data-path-to-node=\"8\" data-index-in-node=\"136\">Marchesi Frescobaldi</b> tại vùng đất <b data-path-to-node=\"8\" data-index-in-node=\"170\">Tuscany</b>. Được phối trộn khéo léo từ giống nho bản địa <b data-path-to-node=\"8\" data-index-in-node=\"224\">Sangiovese</b> cùng chút nhấn thả tinh tế của <b data-path-to-node=\"8\" data-index-in-node=\"266\">Cabernet Sauvignon</b>, Rémole khoác lên mình sắc đỏ ruby tươi tắn, bung tỏa hương thơm mượt mà của mâm xôi, anh đào chín cùng nốt hương thảo mộc địa trung hải thoang thoảng. Cấu trúc vang tròn trịa (medium-bodied), chất tannin mịn màng kết hợp hài hòa với độ chua tự nhiên cân bằng, mang lại cảm giác dễ chịu, sảng khoái và vô cùng dễ uống cho mọi bữa tiệc.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu chính ngạch trọn bộ sưu tập vang Rémole (gồm cả vang đỏ Rémole Rosso và vang trắng Rémole Bianco) với đầy đủ chứng nhận nguồn gốc xuất xứ. Toàn bộ sản phẩm đều được lưu giữ nghiêm ngặt trong hệ thống kho lạnh đạt tiêu chuẩn Cellar khắt khe nhằm giữ trọn độ tươi mới và cấu trúc nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"327\">RUOUCHAT.vn</b> tự hào là điểm đến uy tín giúp bạn dễ dàng sở hữu những chai vang Ý chất lượng chuẩn gu với mức giá tối ưu nhất.</p>', 'Rượu Vang Rémole Frescobaldi Ý Chính Hãng | RUOUCHAT.vn', 'Khám phá Rémole từ nhà Frescobaldi – dòng vang Ý đậm đà phong vị Tuscany. Mua vang Rémole chính hãng, chuẩn vị Terroir với giá tốt nhất tại RUOUCHAT.vn', NULL, 'uploads/category/20260804_143748_6a7196cc2f6e7.jpg', 0, 1, 1),
(89, 'Attems', 'attems', 50, 1, '<h1 data-path-to-node=\"7\" class=\"\" style=\"text-align: center; \">Rượu Vang Attems</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Attems</b> là nhà sản xuất rượu vang danh tiếng có lịch sử lâu đời từ năm 1106, tọa lạc tại tiểu vùng <b data-path-to-node=\"8\" data-index-in-node=\"98\">Collio</b> trù phú thuộc <b data-path-to-node=\"8\" data-index-in-node=\"119\">Friuli-Venezia Giulia (Bắc Ý)</b> – vùng đất được đánh giá là thủ phủ vang trắng cao cấp bậc nhất nước Ý. Hiện thuộc sở hữu của gia tộc lừng danh <b data-path-to-node=\"8\" data-index-in-node=\"261\">Frescobaldi</b>, Attems ghi dấu ấn sâu sắc nhờ việc tận dụng triệt để thổ nhưỡng đá vôi - đất sét giàu khoáng chất (<i data-path-to-node=\"8\" data-index-in-node=\"373\">Ponca</i>) kết hợp với khí hậu cận Alpine tươi mát. Điền trang nổi tiếng với các giống nho trắng thượng hạng như <b data-path-to-node=\"8\" data-index-in-node=\"482\">Pinot Grigio, Sauvignon Blanc</b> và <b data-path-to-node=\"8\" data-index-in-node=\"515\">Ribolla Gialla</b>, mang đến những dòng vang sở hữu sắc vàng ánh xanh lộng lẫy, bung tỏa tầng hương thanh lịch của hoa trắng, quả lê, táo xanh cùng nốt khoáng mặn mòi đặc trưng.</p><p data-path-to-node=\"9\">Sở hữu cấu trúc sảng khoái, độ chua tự nhiên cân bằng và hậu vị kéo dài tinh tế, các sản phẩm vang Attems – tiêu biểu như <i data-path-to-node=\"9\" data-index-in-node=\"122\">Attems Pinot Grigio</i> hay <i data-path-to-node=\"9\" data-index-in-node=\"146\">Cicinis Single Vineyard</i> – luôn là sự lựa chọn hoàn hảo cho các bữa tiệc hải sản cao cấp. Tại <b data-path-to-node=\"9\" data-index-in-node=\"239\">RUOUCHAT.vn</b>, chúng tôi phân phối chính ngạch trọn bộ sưu tập vang Attems với đầy đủ chứng nhận nguồn gốc (CO/CQ). Mọi sản phẩm đều được lưu giữ nghiêm ngặt trong hệ thống kho lạnh chuẩn nhiệt độ Cellar khắt khe, giúp bảo toàn trọn vẹn hương vị tươi mới cùng tiềm năng phát triển tối ưu. <b data-path-to-node=\"9\" data-index-in-node=\"526\">RUOUCHAT.vn</b> tự hào đồng hành cùng quý khách hàng trên hành trình thưởng thức nghệ thuật vang trắng nước Ý đẳng cấp.</p>', 'Rượu Vang Attems Ý Chính Hãng | RUOUCHAT.vn', 'Khám phá Attems – thương hiệu vang trắng hàng đầu Collio Ý. RUOUCHAT.vn phân phối rượu vang Attems chính hãng, chuẩn vị Terroir Friuli cao cấp!', NULL, 'uploads/category/20260804_145625_6a719b2999856.jpg', 0, 1, 1),
(90, 'Tenuta Luce', 'tenuta-luce', 50, 1, '<h1 data-path-to-node=\"7\" style=\"text-align: center;\" class=\"\">Rượu Vang Tenuta Luce</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Tenuta Luce</b> là biểu tượng Super Tuscan lừng danh tại Montalcino (Tuscany, Ý), ra đời từ sự hợp tác lịch sử giữa gia tộc Marchesi Frescobaldi và Robert Mondavi. Điền trang nổi tiếng với triết lý kết hợp hoàn hảo giữa nét cấu trúc đậm đà của <b data-path-to-node=\"8\" data-index-in-node=\"240\">Sangiovese</b> bản địa và sự mượt mà, tròn trịa của <b data-path-to-node=\"8\" data-index-in-node=\"288\">Merlot</b> quốc tế trên thổ nhưỡng đất đá vôi galestro đặc trưng. Rượu vang Tenuta Luce sở hữu sắc đỏ ruby thẫm quý phái, bung tỏa tầng hương phức hợp của quả mọng đen chín cất, việt quất, cacao, cam thảo cùng nốt hương gia vị và gỗ sồi Pháp tinh tế. Cấu trúc vang vô cùng đậm đà (full-bodied), tannin mịn màng như lụa, độ chua cân bằng hoàn hảo mang lại hậu vị trường tồn và tiềm năng lão hóa vượt thời gian.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập Tenuta Luce, từ dòng biểu tượng <i data-path-to-node=\"9\" data-index-in-node=\"110\">Luce della Vite</i>, <i data-path-to-node=\"9\" data-index-in-node=\"127\">Luce Pace</i> cho đến <i data-path-to-node=\"9\" data-index-in-node=\"145\">Lucente</i>. Toàn bộ sản phẩm được lưu giữ khắt khe trong hệ thống kho lạnh tiêu chuẩn Cellar để bảo toàn trọn vẹn hương vị nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"277\">RUOUCHAT.vn</b> tự hào là điểm đến uy tín mang những tuyệt tác vang Ý đẳng cấp nhất đến tay giới thưởng thức Việt.</p>', 'Rượu Vang Tenuta Luce Ý Chính Hãng | RUOUCHAT.vn', 'Khám phá Tenuta Luce – tuyệt tác Super Tuscan Montalcino. RUOUCHAT.vn phân phối rượu vang Tenuta Luce chính hãng, chuẩn vị Terroir đỉnh cao!', NULL, 'uploads/category/20260804_150130_6a719c5a6929f.jpg', 0, 1, 1),
(91, 'Ornellaia', 'ornellaia', 50, 1, '<h1 data-path-to-node=\"7\" style=\"text-align: center; \" class=\"\">Rượu Vang Ornellaia</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Ornellaia</b> là điền trang biểu tượng đỉnh cao của phong cách <b data-path-to-node=\"8\" data-index-in-node=\"59\">Super Tuscan</b>, tọa lạc tại vùng đất vàng <b data-path-to-node=\"8\" data-index-in-node=\"99\">Bolgheri (Tuscany, Ý)</b> ven bờ Địa Trung Hải. Được chế tác từ công thức phối trộn kiểu Bordeaux huyền thoại gồm <b data-path-to-node=\"8\" data-index-in-node=\"209\">Cabernet Sauvignon, Merlot, Cabernet Franc</b> và <b data-path-to-node=\"8\" data-index-in-node=\"255\">Petit Verdot</b>, Ornellaia thể hiện sự hòa hợp hoàn hảo giữa thổ nhưỡng đất sét - đá vôi giàu khoáng chất và kỹ thuật ủ gỗ sồi Pháp tỉ mỉ. Rượu mang sắc đỏ ruby thẫm sang trọng, bung tỏa tầng hương phức hợp của quả mọng đen, mứt mận, xì-gà, cacao cùng nốt hương gia vị và thảo mộc khô quyến rũ. Cấu trúc vang vô cùng đậm đà (full-bodied), tannin mịn như lụa, độ chua sống động mang lại hậu vị kéo dài bất tận và tiềm năng lưu trữ qua nhiều thập kỷ.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập Ornellaia (bao gồm dòng biểu tượng <i data-path-to-node=\"9\" data-index-in-node=\"113\">Ornellaia Bolgheri Superiore</i> và <i data-path-to-node=\"9\" data-index-in-node=\"145\">Le Serre Nuove dell\'Ornellaia</i>). Toàn bộ sản phẩm được bảo quản khắt khe trong kho lạnh chuyên dụng chuẩn nhiệt độ Cellar để giữ trọn vẹn chất lượng nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"305\">RUOUCHAT.vn</b> tự hào là địa chỉ uy tín đồng hành cùng các tín đồ sành vang trên hành trình thưởng thức tuyệt tác vang Ý đẳng cấp bậc nhất thế giới.</p>', '', '', NULL, 'uploads/category/20260804_150340_6a719cdc69814.png', 0, 1, 1);
INSERT INTO `categories` (`id`, `name`, `slug`, `parent_id`, `level`, `description`, `seo_title`, `seo_description`, `meta_description`, `image`, `order_position`, `status`, `is_producer`) VALUES
(92, 'Tenuta di Biserno', 'tenuta-di-biserno', 50, 1, '<h1 data-path-to-node=\"7\" style=\"text-align: center; \" class=\"\">Rượu Vang Tenuta di Biserno</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Tenuta di Biserno</b> là điền trang Super Tuscan đỉnh cao tại vùng Bibbona (Tuscany, Ý), được sáng lập bởi huyền thoại Marquis Lodovico Antinori – người khai sinh ra Ornellaia. Tọa lạc sát ranh giới dải đất vàng Bolgheri, Biserno sở hữu Terroir độc đáo với chất đất sét giàu sỏi dăm, đá vôi cùng vi khí hậu biển Địa Trung Hải ấm áp. Điền trang nổi tiếng với phong cách phối trộn Bordeaux kiểu bờ trái tinh tế, tập trung vào các giống nho <b data-path-to-node=\"8\" data-index-in-node=\"434\">Cabernet Franc, Merlot, Cabernet Sauvignon</b> và <b data-path-to-node=\"8\" data-index-in-node=\"480\">Petit Verdot</b>. Rượu vang mang sắc đỏ ruby thẫm, bung tỏa tầng hương phức hợp của quả mọng đen, xì-gà, cacao, thảo mộc khô và khoáng chất sắc nét. Cấu trúc vang vô cùng đậm đà (full-bodied), tannin mịn như lụa, độ chua sống động mang đến hậu vị kéo dài bất tận cùng tiềm năng lưu trữ vượt thời gian.</p><p data-path-to-node=\"9\">Tại <b data-path-to-node=\"9\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập Tenuta di Biserno (từ dòng biểu tượng <i data-path-to-node=\"9\" data-index-in-node=\"116\">Biserno</i>, <i data-path-to-node=\"9\" data-index-in-node=\"125\">Il Pino di Biserno</i> đến <i data-path-to-node=\"9\" data-index-in-node=\"148\">Insoglio del Cinghiale</i>). Toàn bộ sản phẩm được bảo quản khắt khe trong kho lạnh chuyên dụng chuẩn tiêu chuẩn Cellar nhằm duy trì trọn vẹn chất lượng nguyên bản. <b data-path-to-node=\"9\" data-index-in-node=\"309\">RUOUCHAT.vn</b> tự hào là điểm đến uy tín đồng hành cùng giới thưởng thức trên hành trình khám phá những kiệt tác vang Ý thượng hạng.</p>', 'Rượu Vang Tenuta di Biserno Super Tuscan | RUOUCHAT.vn', 'Khám phá Tenuta di Biserno – tuyệt tác Super Tuscan từ Lodovico Antinori. Mua vang Biserno chính hãng, chuẩn vị Terroir Bolgheri tại RUOUCHAT.vn!', NULL, 'uploads/category/20260804_150616_6a719d78e7a93.jpg', 0, 1, 1),
(93, 'Casanova di Neri', 'casanova-di-neri', 50, 1, '<h1 data-path-to-node=\"7\">Rượu Vang Casanova di Neri</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Casanova di Neri</b> là nhà sản xuất rượu vang huyền thoại được thành lập từ năm 1971 bởi Giovanni Neri, tọa lạc tại vùng đất danh giá <b data-path-to-node=\"8\" data-index-in-node=\"131\">Montalcino (Tuscany, Ý)</b>. Điền trang nổi tiếng thế giới khi liên tục giành được những điểm số tuyệt đối 100/100 từ các chuyên gia nhờ nâng tầm giống nho <b data-path-to-node=\"8\" data-index-in-node=\"283\">Sangiovese Grosso</b> (Brunello) trên nền thổ nhưỡng đất đá vôi, đất sét giàu khoáng chất <i data-path-to-node=\"8\" data-index-in-node=\"369\">Galestro</i>. Quá trình lên men tự nhiên cùng kỹ thuật ủ khắt khe trong các thùng gỗ sồi lớn mang đến cho vang Casanova di Neri màu đỏ ruby sẫm lộng lẫy, bung tỏa tầng hương phức hợp của anh đào dại, mứt mận, da thuộc, xì-gà, cam thảo và khoáng chất sắc nét.</p><p data-path-to-node=\"9\">Cấu trúc vang vô cùng đậm đà (full-bodied), chất tannin mịn như lụa cùng độ chua tự nhiên cân bằng hoàn hảo, mở ra hậu vị trường tồn và tiềm năng lão hóa hàng thập kỷ. Tại <b data-path-to-node=\"9\" data-index-in-node=\"172\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập Casanova di Neri – tiêu biểu như <i data-path-to-node=\"9\" data-index-in-node=\"279\">Brunello di Montalcino DOCG</i>, <i data-path-to-node=\"9\" data-index-in-node=\"308\">Tenuta Nuova</i> hay tuyệt tác <i data-path-to-node=\"9\" data-index-in-node=\"335\">Cerretalto</i>. Toàn bộ sản phẩm được lưu giữ nghiêm ngặt trong hệ thống kho lạnh chuyên dụng chuẩn tiêu chuẩn Cellar để bảo toàn trọn vẹn giá trị Terroir nguyên bản đến tay giới thưởng thức.</p>', 'Rượu Vang Casanova di Neri Ý | RUOUCHAT.vn', 'Khám phá Casanova di Neri – huyền thoại Brunello di Montalcino. RUOUCHAT.vn phân phối rượu vang Casanova di Neri chính hãng, chuẩn vị Terroir đỉnh cao!', NULL, 'uploads/category/20260804_150827_6a719dfb68cfd.png', 0, 1, 1),
(94, 'Castellare di Castellina', 'castellare-di-castellina', 50, 1, '<h1 data-path-to-node=\"7\" style=\"text-align: center; \" class=\"\">Rượu Vang Castellare di Castellina</h1><p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">Castellare di Castellina</b> là điền trang biểu tượng tọa lạc tại trái tim tiểu vùng <b data-path-to-node=\"8\" data-index-in-node=\"81\">Chianti Classico (Tuscany, Ý)</b>, nổi tiếng với triết lý sản xuất hữu cơ và tôn trọng hệ sinh thái tự nhiên. Điền trang ghi dấu ấn sâu sắc khi phục dựng giống nho bản địa <b data-path-to-node=\"8\" data-index-in-node=\"249\">Sangioveto</b> (dòng clone nguyên bản của Sangiovese) kết hợp cùng <b data-path-to-node=\"8\" data-index-in-node=\"312\">Malvasia Nera</b>, phát triển trên nền thổ nhưỡng marly-limestone đá vôi giàu khoáng chất ở độ cao 400m. Quá trình lên men truyền thống cùng kỹ thuật ủ trong thùng gỗ sồi Pháp mang đến cho rượu sắc đỏ ruby thẫm quý phái, bung tỏa tầng hương phức hợp của anh đào dại, mứt mận, cam thảo, xì-gà và thảo mộc địa trung hải.</p><p data-path-to-node=\"9\">Cấu trúc vang đậm đà vừa phải (medium-to-full-bodied), tannin mịn màng, độ chua tự nhiên sống động mang lại hậu vị sâu lắng và tiềm năng lưu trữ qua nhiều năm. Tại <b data-path-to-node=\"9\" data-index-in-node=\"164\">RUOUCHAT.vn</b>, chúng tôi nhập khẩu và phân phối chính ngạch trọn bộ sưu tập Castellare di Castellina – từ dòng <i data-path-to-node=\"9\" data-index-in-node=\"273\">Chianti Classico DOCG</i> đặc trưng cho đến tuyệt tác Super Tuscan <i data-path-to-node=\"9\" data-index-in-node=\"336\">I Sodi di S. Niccolò</i>. Toàn bộ sản phẩm được bảo quản khắt khe trong hệ thống kho lạnh chuyên dụng chuẩn nhiệt độ Cellar để giữ trọn vẹn giá trị Terroir nguyên bản đến tay quý khách hàng.</p>', 'Rượu Vang Castellare di Castellina Ý | RUOUCHAT.vn', 'Khám phá Castellare di Castellina – biểu tượng Chianti Classico hữu cơ. Mua vang Castellare di Castellina chính hãng, chuẩn Terroir tại RUOUCHAT.vn!', NULL, 'uploads/category/20260804_150948_6a719e4cc0949.jpg', 0, 1, 1),
(95, 'Sandrone', 'sandrone', 50, 1, '<h1 data-path-to-node=\"3\" style=\"text-align: center; \" class=\"\">Rượu Vang Luciano Sandrone</h1><p data-path-to-node=\"4\">Luciano Sandrone là một trong những nhà làm vang biểu tượng đỉnh cao của vùng Piemonte, Ý, đại diện xuất sắc cho trường phái Barolo Hiện đại (Modernist Barolo). Nổi tiếng thế giới với phong cách làm vang tinh tế, Sandrone đã nâng tầm giống nho Nebbiolo truyền thống nhờ kỹ thuật kiểm soát nhiệt độ lên men nghiêm ngặt và quá trình ủ trong thùng gỗ sồi French oak tôn vinh trọn vẹn terroir độc bản.</p><p data-path-to-node=\"5\">Những dòng vang huyền thoại như <b data-path-to-node=\"5\" data-index-in-node=\"32\">Sandrone Barolo Le Vigne</b> hay <b data-path-to-node=\"5\" data-index-in-node=\"61\">Barolo Cannubi Boschis</b> (sau này là Aleste) luôn chinh phục các chuyên gia thẩm định quốc tế nhờ cấu trúc tannin mượt mà, độ chua thanh thoát cùng tầng hương thơm phức hợp của quả mộng đỏ, hoa hồng khô, cam thảo và da thuộc. Mỗi niên vụ từ hầm rượu Sandrone đều thể hiện sự cân bằng hoàn hảo giữa sức mạnh nội tại và sự uyển chuyển tinh tế, sở hữu khả năng lưu trữ (aging potential) tiềm năng lên đến hàng thập kỷ.</p><p data-path-to-node=\"6\">Tại <b data-path-to-node=\"6\" data-index-in-node=\"4\">RUOUCHAT.vn</b>, chúng tôi tự hào phân phối các dòng rượu vang Luciano Sandrone nhập khẩu chính hãng với đầy đủ chứng nhận nguồn gốc và điều kiện bảo quản chuẩn hầm rượu chuyên nghiệp. Quý khách hàng và giới thưởng thức có thể dễ dàng tìm kiếm những chai Sandrone thượng hạng để bổ sung vào bộ sưu tập cá nhân hoặc làm quà tặng doanh nghiệp đẳng cấp. Liên hệ ngay với đội ngũ chuyên gia tại RUOUCHAT.vn để nhận tư vấn chuyên sâu và báo giá ưu đãi nhất.</p>', 'Rượu Vang Sandrone Nhập Khẩu Chính Hãng | Giá Tốt - RUOUCHAT.vn', 'Khám phá rượu vang Luciano Sandrone chính hãng từ Barolo, Ý tại RUOUCHAT.vn. Đầy đủ các dòng Barolo Cannubi Boschis, Le Vigne giá tốt. Tư vấn ngay!', NULL, 'uploads/category/20260804_153509_6a71a43da5299.jpg', 0, 1, 1),
(96, 'Vietti', 'vietti', 50, 1, '<p data-path-to-node=\"9\">Mua một chai rượu vang cao cấp không đơn thuần là giao dịch thương mại, mà là sự đầu tư cho cảm xúc và trải nghiệm vị giác. Tuy nhiên, giữa hàng ngàn nhãn hiệu trên thị trường, làm sao để tìm được một thương hiệu vừa mang bề dày lịch sử, vừa sở hữu phẩm chất vượt trội để biếu tặng đối tác hay thưởng thức trong những dịp trọng đại?</p><p data-path-to-node=\"10\">Nếu bạn đang tìm kiếm sự hoàn hảo từ vùng đất Piedmont (Bắc Ý) – nơi khai sinh ra những dòng vang Barolo danh giá nhất thế giới – <b data-path-to-node=\"10\" data-index-in-node=\"130\">Vietti</b> chính là câu trả lời trọn vẹn nhất. Tại <b data-path-to-node=\"10\" data-index-in-node=\"177\">Ruouchat.vn</b>, chúng tôi mang đến bộ sưu tập rượu vang Vietti nhập khẩu chính hãng, đầy đủ giấy tờ chứng nhận xuất xứ, giúp bạn hoàn toàn yên tâm khi lựa chọn.</p>\r\n', '', '', NULL, 'uploads/category/20260804_161607_6a71add7dac6e.jpg', 0, 1, 1),
(97, 'Aglianico', 'aglianico', 46, 1, '<h1 class=\"\" style=\"text-align: center; \">Rượu Vang Aglianico</h1><p data-path-to-node=\"13\">Aglianico là một trong những giống nho đỏ lâu đời nhất còn tồn tại trên thế giới. Giống nho này được người Hy Lạp cổ đại đưa đến miền Nam nước Ý từ thế kỷ thứ 6 hoặc thứ 7 TCN (tên gọi \"Aglianico\" được cho là biến thể từ từ \"Hellenic\" - nghĩa là thuộc về Hy Lạp).</p><p data-path-to-node=\"14\">Khác với các giống nho đỏ phát triển ở vùng đồng bằng ấm áp, Aglianico là giống nho nảy mầm sớm nhưng <b data-path-to-node=\"14\" data-index-in-node=\"102\">chín rất muộn</b> (thường được thu hoạch vào cuối tháng 10 hoặc đầu tháng 11). Giống nho này đòi hỏi nhiều ánh nắng mặt trời nhưng lại cần độ cao địa hình và khí hậu mát mẻ để tích tụ hương thơm mà không làm mất đi độ chua tự nhiên.</p><p data-path-to-node=\"15\">Thổ nhưỡng lý tưởng nhất của Aglianico chính là <b data-path-to-node=\"15\" data-index-in-node=\"48\">đất đá núi lửa ngàn năm</b> tại hai vùng đất huyền thoại:</p><ul data-path-to-node=\"16\"><li><p data-path-to-node=\"16,0,0\"><b data-path-to-node=\"16,0,0\" data-index-in-node=\"0\">Taurasi (vùng Campania):</b> Nằm trên các sườn đồi núi lửa lửa Vesuvio đã ngưng hoạt động. Rượu vang Aglianico tại đây đạt cấp độ DOCG cao nhất, được mệnh danh là <i data-path-to-node=\"16,0,0\" data-index-in-node=\"159\">\"Barolo của miền Nam\"</i> nhờ cấu trúc tannin uy nghi và khả năng lão hóa phi thường.</p></li><li><p data-path-to-node=\"16,1,0\"><b data-path-to-node=\"16,1,0\" data-index-in-node=\"0\">Aglianico del Vulture (vùng Basilicata):</b> Trồng xung quanh chân núi lửa Vulture đã tắt. Thổ nhưỡng giàu khoáng chất tro núi lửa mang lại cho vang hương vị khoáng đượm đà, vị chát mượt mà và nốt hương hoa nhài, anh đào đen độc đáo.</p></li></ul>', 'Rượu Vang Aglianico Chính Hãng: Đỉnh Cao Nam Ý | Ruouchat.vn', 'Khám phá rượu vang Aglianico chính hãng từ Nam Ý tại Ruouchat.vn. Hương vị đậm đà, tannin rắn rỏi, tư vấn chuẩn chuyên gia. Mua ngay giá tốt!', NULL, '', 0, 1, 0),
