INSERT INTO `producers` (`id`, `name`, `slug`, `country`, `description`, `image`, `status`, `is_featured`) VALUES
(1, 'Domaine Faiveley', 'domaine-faiveley', 'Pháp', NULL, NULL, 1, 1),
(5, 'Château Dauzac', 'chteau-dauzac', NULL, NULL, NULL, 1, 0),
(6, 'Altano Douro', 'altano-douro', '', 'Altano Douro là đại diện tiêu biểu cho phong cách làm vang hiện đại tại thung lũng Douro, Bồ Đào Nha, nơi những vườn nho cổ thụ trên nền đất đá phiến (schist) tạo nên chiều sâu hương vị độc bản. Với sự phối trộn từ các giống nho bản địa truyền thống như Touriga Nacional và Tinta Roriz, dòng vang này thể hiện sự cân bằng hoàn hảo giữa tannin mượt mà và hương thơm trái cây chín mọng.\r\n\r\nQuy trình ủ nghiêm ngặt giúp Altano Douro đạt được cấu trúc bền bỉ, mang lại hậu vị kéo dài đầy ấn tượng cho người thưởng thức. Tại RUOUCHAT.vn, chúng tôi tuyển chọn kỹ lưỡng từng chai Altano để đảm bảo tính nguyên bản và chất lượng thượng hạng đến tay khách hàng. Đây không chỉ là một lựa chọn rượu vang đơn thuần, mà là hành trình trải nghiệm di sản văn hóa và kỹ thuật canh tác đặc trưng từ vùng đất di sản thế giới UNESCO. Nếu quý khách cần thông tin chi tiết về kỹ thuật (Technical Data Sheet) hoặc tư vấn phối ghép món ăn, đội ngũ chuyên gia của RUOUCHAT.vn luôn sẵn sàng hỗ trợ.', '', 1, 0),
(7, 'Caviro', 'caviro', '', 'Caviro là hợp tác xã rượu vang hàng đầu nước Ý, nổi danh với quy trình kiểm soát chất lượng khắt khe từ vườn nho đến khi đóng chai. Với triết lý tôn trọng thổ nhưỡng (terroir) và ứng dụng kỹ thuật sản xuất hiện đại, Caviro mang đến những dòng vang có độ ổn định tuyệt vời, làm nổi bật đặc tính của các giống nho bản địa như Sangiovese hay Trebbiano. Sự kết hợp giữa quy mô sản xuất lớn và tâm huyết của hàng ngàn nông dân giúp mỗi sản phẩm đạt được cấu trúc hài hòa, hương vị phong phú nhưng vẫn giữ mức giá đầy cạnh tranh.\r\n\r\nTại RUOUCHAT.vn, chúng tôi tuyển chọn những chai vang tiêu biểu nhất từ Caviro để đáp ứng đa dạng nhu cầu, từ thưởng thức hàng ngày đến phục vụ tiệc cao cấp. Dòng sản phẩm này không chỉ đại diện cho phong cách làm vang Ý truyền thống mà còn là minh chứng cho sự tối ưu hóa kỹ thuật trong ngành công nghiệp đồ uống toàn cầu. Đội ngũ chuyên gia tại RUOUCHAT.vn sẵn sàng cung cấp các thông tin chi tiết về đặc điểm vùng trồng (appellation) và gợi ý kết hợp ẩm thực để tối ưu trải nghiệm thưởng thức vang của quý khách hàng.', '', 1, 0),
(8, 'Collefrisio', 'collefrisio', '', '', 'uploads/producers/1784002595_6a55b82361e78.png', 1, 1),
(11, 'GlenAllachie', 'glenallachie', '', 'GlenAllachie là biểu tượng của nghệ thuật làm Whisky tại Speyside, nổi bật với quy trình ủ rượu tỉ mỉ trong các loại thùng gỗ sồi tuyển chọn, tạo nên cấu trúc hương vị vô cùng phức hợp. Dưới sự dẫn dắt của bậc thầy chưng cất Billy Walker, GlenAllachie mang đến những dòng Single Malt có tầng hương đặc trưng của mật ong, gia vị ấm nồng và trái cây sấy đậm đà, phản ánh trung thực bản sắc vùng Terroir độc bản. Tại RUOUCHAT.vn, chúng tôi thấu hiểu giá trị của từng niên vụ, do đó mỗi chai GlenAllachie đều được kiểm định khắt khe về thông số kỹ thuật và điều kiện bảo quản.\r\n\r\nChúng tôi cung cấp dữ liệu chuyên sâu về độ tuổi (aging), loại thùng ủ và đặc tính hương vị, giúp giới mộ điệu dễ dàng nắm bắt sự tinh túy trong từng giọt rượu. RUOUCHAT.vn không chỉ cung cấp sản phẩm mà còn khẳng định vị thế dẫn đầu trong việc định hình trải nghiệm thưởng thức Whisky đẳng cấp tại thị trường Việt Nam. Mỗi chai rượu khi đến tay khách hàng đều giữ trọn vẹn đặc tính nguyên bản từ nhà chưng cất, đáp ứng yêu cầu khắt khe nhất của các nhà sưu tầm. Hãy khám phá ngay bộ sưu tập GlenAllachie tại website để nâng tầm trải nghiệm thưởng thức với tiêu chuẩn chất lượng cao cấp nhất.', '', 1, 1),
(12, 'Tamdhu', 'tamdhu', '', 'Tamdhu là đại diện tiêu biểu cho phong cách Speyside cổ điển, nổi danh với triết lý sử dụng 100% thùng gỗ sồi Sherry Oloroso để chưng cất, tạo nên sắc màu tự nhiên sâu đậm cùng cấu trúc hương vị đặc trưng. Quá trình lão hóa kéo dài trong những thùng Sherry thượng hạng mang đến cho Tamdhu các tầng hương phức hợp của trái cây khô, gia vị ấm nồng và socola đen, phản ánh trung thực bản sắc vùng Terroir màu mỡ của Scotland. Tại RUOUCHAT.vn, chúng tôi thấu hiểu giá trị của di sản này nên luôn ưu tiên các phiên bản giới hạn, đảm bảo thông số kỹ thuật chuẩn xác về độ tuổi (aging) và phương pháp ủ.\r\n\r\nViệc sở hữu một chai Tamdhu không chỉ là thưởng thức nghệ thuật chưng cất đỉnh cao mà còn là sự thấu hiểu về sự kiên định trong việc bảo tồn chất lượng truyền thống. Đội ngũ RUOUCHAT.vn cam kết cung cấp dữ liệu minh bạch, giúp giới mộ điệu cảm nhận trọn vẹn sự tinh túy từ mỗi giọt rượu khi thưởng thức tại gia. Mỗi sản phẩm được bảo quản trong môi trường tối ưu, giữ nguyên vẹn giá trị cốt lõi từ nhà chưng cất danh tiếng đến tay khách hàng. Hãy khám phá ngay bộ sưu tập Tamdhu tại RUOUCHAT.vn để khẳng định đẳng cấp và gu thưởng thức vang tầm cỡ của riêng bạn.', '', 1, 1),
(13, 'Cognac Lheraud', 'cognac-lheraud', 'Pháp', 'Cognac Lheraud là hiện thân của nghệ thuật chưng cất thủ công vùng Petite Champagne, nơi gia tộc Lheraud duy trì triết lý sản xuất không pha trộn và không phụ gia. Mỗi chai rượu đều là kết quả của sự kiên nhẫn trong các thùng gỗ sồi cổ xưa, mang đến cấu trúc hương vị đặc thù của trái cây sấy, mật ong rừng và các nốt gia vị quý hiếm. Tại RUOUCHAT.vn, chúng tôi tự hào mang đến những phiên bản Cognac Lheraud Vintage hiếm có, nơi mà thời gian và terroir được cô đọng trong từng giọt rượu, đáp ứng sự mong đợi của những nhà sưu tầm khắt khe nhất.\r\n\r\nVới nền tảng dữ liệu kỹ thuật minh bạch, RUOUCHAT.vn giúp quý khách hàng thấu hiểu sâu sắc giá trị của từng niên vụ, từ phương pháp chưng cất nồi tĩnh truyền thống đến quy trình đóng chai chuẩn mực. Mỗi sản phẩm khi đến tay khách hàng đều được cam kết bảo quản trong điều kiện lý tưởng, giữ trọn vẹn bản sắc nguyên bản và sự sang trọng vốn có của thương hiệu Lheraud danh tiếng. Hãy khám phá ngay bộ sưu tập tại website để nâng tầm trải nghiệm thưởng thức, khẳng định gu thẩm mỹ tinh tế và niềm đam mê với di sản rượu mạnh Pháp đích thực.', '', 1, 1);

