--
-- Cấu trúc bảng cho bảng `products`
--

CREATE TABLE `products` (
  `id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `old_price` decimal(10,2) DEFAULT NULL,
  `abv` varchar(20) DEFAULT NULL,
  `volume` varchar(20) DEFAULT NULL,
  `grape_type` varchar(100) DEFAULT NULL,
  `wine_type` varchar(50) DEFAULT NULL,
  `region` varchar(100) DEFAULT NULL,
  `country` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `producer_id` int(11) DEFAULT NULL,
  `status` tinyint(4) DEFAULT 1,
  `featured` tinyint(4) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `schedule_start` datetime DEFAULT NULL,
  `schedule_end` datetime DEFAULT NULL,
  `product_type` int(11) DEFAULT NULL COMMENT 'ID loại sản phẩm từ bảng product_types',
  `spirit_type` varchar(100) DEFAULT NULL,
  `brand` varchar(100) DEFAULT NULL,
  `age` varchar(50) DEFAULT NULL,
  `stock_quantity` int(11) NOT NULL DEFAULT 0,
  `seo_title` varchar(255) DEFAULT NULL,
  `seo_description` text DEFAULT NULL,
  `seo_keywords` text DEFAULT NULL,
  `sku` varchar(100) DEFAULT NULL,
  `barcode` varchar(100) DEFAULT NULL,
  `weight_gram` int(11) DEFAULT 0,
  `dynamic_attributes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `variants` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `tags` text DEFAULT NULL,
  `requires_special_shipping` tinyint(4) DEFAULT 0 COMMENT '1: Có yêu cầu vận chuyển đặc biệt',
  `auto_status_update` tinyint(4) DEFAULT 1 COMMENT '1: Tự động cập nhật trạng thái',
  `display_status` enum('visible','hidden','coming_soon','discontinued','draft') DEFAULT 'visible'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Đang đổ dữ liệu cho bảng `products`
--

INSERT INTO `products` (`id`, `name`, `slug`, `price`, `old_price`, `abv`, `volume`, `grape_type`, `wine_type`, `region`, `country`, `description`, `producer_id`, `status`, `featured`, `created_at`, `schedule_start`, `schedule_end`, `product_type`, `spirit_type`, `brand`, `age`, `stock_quantity`, `seo_title`, `seo_description`, `seo_keywords`, `sku`, `barcode`, `weight_gram`, `dynamic_attributes`, `variants`, `tags`, `requires_special_shipping`, `auto_status_update`, `display_status`) VALUES
(73, 'Rượu Vang Ý Con Công Vindoro Negroamaro', 'vang-con-cong-vindoro-negroamaro', '99999999.99', '99999999.99', '15', '750', '129', NULL, '', '', '<h2 style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\"><span style=\"font-weight: bolder;\">Vindoro Negroamaro – Tinh hoa đất trời</span></h2><p style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Ra mắt vào năm 2015, Vindoro đã trở thành một hiện tượng trong giới sành vang toàn cầu. Từ nước Ý đến Việt Nam, Vindoro được biết đến với cái tên thân mật \"rượu vang con công\", một dòng vang đỏ nổi tiếng của thương hiệu San Marzano ở Nam Ý.</p><p style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><img alt=\"Vindoro Negroamaro\" data-thumb=\"original\" original-height=\"600\" original-width=\"800\" src=\"https://bizweb.dktcdn.net/100/441/574/files/ruou-vang-y-con-cong-vindoro-negroamaro-9.jpg?v=1759398512582\" style=\"border: 0px; max-width: 100%; height: auto !important;\"></p><p style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Trong những năm gần đây, việc chọn Vindoro làm quà tặng doanh nghiệp đã trở thành xu hướng phổ biến.</p><h2 style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\"><span style=\"font-weight: bolder;\">San Marzano – Thương hiệu danh tiếng vùng Nam Ý</span></h2><p style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Vindoro là một trong những dòng vang chủ lực của Cantine San Marzano. Nằm ở trung tâm khu vực Primitivo di Manduria D.O.C tại Puglia, San Marzano là thương hiệu rượu vang hàng đầu vùng Nam Ý. Từ năm 1962, với sự nỗ lực không ngừng, San Marzano đã đạt được nhiều thành công lớn trên thị trường trong nước và quốc tế.</p><p style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><img alt=\"Rượu Vang Ý Con Công Vindoro Negroamaro\" data-thumb=\"original\" original-height=\"600\" original-width=\"600\" src=\"https://bizweb.dktcdn.net/100/441/574/products/ruou-vang-y-con-cong-vindoro-negroamaro-1.jpg?v=1735630948377\" style=\"border: 0px; max-width: 100%; height: auto !important;\"></p><p style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Với niềm đam mê và tâm huyết dành cho các giống nho đặc trưng của Puglia, San Marzano liên tục cải tiến phương pháp sản xuất để nâng cao chất lượng rượu vang, tạo ra những dòng vang thơm ngon tuyệt hảo.</p><h2 style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\"><span style=\"font-weight: bolder;\">Giống nho làm nên Vindoro</span></h2><p style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\"><span style=\"font-weight: bolder;\"><a href=\"https://vangchat.vn/vang-do/\" style=\"color: rgb(0, 0, 0); text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"color: rgb(192, 57, 43);\">Rượu vang đỏ</span></a></span> Vindoro được làm từ những cây nho Negroamaro cổ thụ, được nuôi dưỡng trên đất đai quý giá và chất lượng cao của Masseria Samia, mang đậm hơi thở của vùng đất giữa đại dương.</p><p style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Sự kết hợp giữa thổ nhưỡng, nắng gió, thiên nhiên hoang dã và nhiệt huyết của San Marzano đã tạo nên hương vị phức hợp và đậm đà của rượu vang Vindoro.</p>', NULL, 1, 0, '2026-05-25 15:19:34', NULL, NULL, 1, NULL, NULL, '', 5, 'Rượu Vang Con Công - Rượu Vang Ý', 'Rượu vang con công\" Vindoro hứa hẹn sẽ là món quà tặng ý nghĩa và đẳng cấp cho mùa lễ hội năm nay. Chim công, biểu tượng của sự may mắn và thịnh vượng trong văn hóa phương Đông, gửi gắm lời chúc một năm mới phúc lộc đầy nhà.', NULL, 'VT/0621', '', 0, '[]', '[]', NULL, 0, 1, 'visible'),
(93, 'Rượu Vang Kimi Sauvignon Blanc', 'ruou-vang-kimi-sauvignon-blanc', '99999999.99', '99999999.99', '', '', '', NULL, '', '', '<p data-path-to-node=\"5\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\"><span data-index-in-node=\"0\" data-path-to-node=\"5\" style=\"font-weight: bolder;\">Kimi Marlborough Sauvignon Blanc</span> là một trong những đại diện tiêu biểu cho phong cách vang trắng hiện đại của New Zealand, nổi bật với hương thơm mãnh liệt độc bản và độ chua sảng khoái. Với hương vị trái cây nhiệt đới sống động, đây là lựa chọn hoàn hảo cho những ai yêu thích sự tươi mới, đặc biệt thích hợp cho các bữa tiệc hải sản ngoài trời hoặc những ngày hè oi ả.</p><p data-path-to-node=\"5\" style=\"text-align: center; margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\"><img src=\"https://ruouchat.vn/api/../uploads/product_desc/2026/06/20260602_082141_3b8d37fcc771ba70.webp\" alt=\"kimi sauvignon blanc\" style=\"max-width:100%\"><br></p><p data-path-to-node=\"5\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"></p><p data-path-to-node=\"5\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><span style=\"font-weight: bolder;\">Rượu vang trắng Kimi Sauvignon Blanc Đạt Huy chương vàng năm 2026 Tại Cuộc Thi Rượu Vang London</span></p><h2 data-path-to-node=\"12\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Điều gì làm Kimi Sauvignon Blanc khác biệt?</h2><p data-path-to-node=\"13\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Marlborough không chỉ là một vùng địa lý, đó là \"thánh địa\" tạo nên danh tiếng cho Sauvignon Blanc toàn cầu. Điều gì đã nhào nặn nên tính cách đặc trưng của Kimi?</p><h3 data-path-to-node=\"14\" style=\"margin-bottom: 0.5rem; font-weight: 500; line-height: 1.4; font-size: 1.75rem; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Khí hậu độc nhất của vùng Marlborough</h3><p data-path-to-node=\"15\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Sự khác biệt nằm ở biên độ nhiệt ngày và đêm rất lớn. Ban ngày, vùng nhận được lượng nắng mạnh mẽ giúp nho tích tụ lượng đường và hương vị trái cây nhiệt đới (tropical fruit) tối đa. Ban đêm, luồng gió biển lạnh tràn vào giúp làm mát các sườn đồi, làm chậm quá trình chín và giữ lại hàm lượng acid tự nhiên vô cùng quý giá cho quả nho.</p><p data-path-to-node=\"15\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><img src=\"https://bizweb.dktcdn.net/100/441/574/files/giong-nho-sauvignon-blanc_dcc2eb74-9e84-4f82-90e6-312f135a14a6.jpg?v=1780027361507\" style=\"border: 0px; max-width: 100%; height: auto !important;\"></p><p data-path-to-node=\"15\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><span style=\"font-weight: bolder;\">Hình ảnh chùm nho Sauvignon Blanc</span></p><h3 data-path-to-node=\"16\" style=\"margin-bottom: 0.5rem; font-weight: 500; line-height: 1.4; font-size: 1.75rem; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Phong cách Kimi thiên về xu hướng nào?</h3><p data-path-to-node=\"17\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Trong khi một số chai <a href=\"https://wine1855.vn/sauvignon-blanc\" style=\"text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-weight: bold; color: rgb(201, 76, 62) !important;\">Sauvignon Blanc</a> của Tân Thế Giới đi theo hướng quá nồng gắt mùi cỏ khô, Kimi chọn lối đi cân bằng hơn. Chai vang này nghiêng hẳn về <span data-path-to-node=\"17\" data-index-in-node=\"154\" style=\"font-weight: bolder;\">style Tropical Fruit (Trái cây nhiệt đới)</span> kết hợp với <span data-path-to-node=\"17\" data-index-in-node=\"208\" style=\"font-weight: bolder;\">Citrus (Cam quýt)</span>. Nó sở hữu độ <i data-path-to-node=\"17\" data-index-in-node=\"240\">aromatic intensity</i> (cường độ hương thơm) rất mạnh nhưng hậu vị lại được làm mềm mượt, giúp người uống không có cảm giác bị \"mệt\" vị giác sau ly thứ hai.</p><p data-path-to-node=\"17\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\"><img src=\"https://ruouchat.vn/api/../uploads/product_desc/2026/06/20260602_082610_1ee5fabb726ceeef.jpg\" alt=\"ruou vang vung Abruzzo\" style=\"max-width:100%\"><br></p><h2 data-path-to-node=\"7\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Hương vị rượu vang trắng Kimi Sauvignon Blanc</h2><p data-path-to-node=\"8\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Để giúp bạn nhanh chóng hình dung phong cách của chai vang này trước khi quyết định chọn mua, dưới đây là những ghi chú nếm thử chi tiết nhất về mặt cảm quan:</p><ul data-path-to-node=\"9\" style=\"margin-bottom: 15px; list-style: initial; padding-left: 25px; font-family: Roboto, sans-serif; font-size: 14px;\"><li><p data-path-to-node=\"9,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"9,0,0\" style=\"font-weight: bolder;\">Hương thơm :</span> Ngay khi vừa rót ra ly, Kimi bung tỏa hương thơm đậm nét của chanh dây, bưởi hồng, quả lý gai, xen lẫn nốt hương thảo mộc của cỏ tươi cắt dầy và vỏ chanh bào nhuyễn.</p></li><li><p data-path-to-node=\"9,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"9,1,0\" style=\"font-weight: bolder;\">Khi uống :</span></p><ul data-path-to-node=\"9,1,1\" style=\"margin-bottom: 15px; list-style: initial; padding-left: 25px;\"><li><p data-path-to-node=\"9,1,1,0,0\" style=\"margin: 0px 0px 15px;\"><i data-index-in-node=\"0\" data-path-to-node=\"9,1,1,0,0\">Độ acid:</i> Sắc nét, cao và vô cùng sống động (crisp acidity), tạo cảm giác sảng khoái tức thì.</p></li><li><p data-path-to-node=\"9,1,1,1,0\" style=\"margin: 0px 0px 15px;\"><i data-index-in-node=\"0\" data-path-to-node=\"9,1,1,1,0\">Thân chai &amp; Cấu trúc :</i> Thân nhẹ đến trung bình (light-to-medium body), kết cấu mượt mà, sạch sẽ.</p></li><li><p data-path-to-node=\"9,1,1,2,0\" style=\"margin: 0px 0px 15px;\"><i data-index-in-node=\"0\" data-path-to-node=\"9,1,1,2,0\">Độ tươi :</i> Tràn đầy năng lượng với vị trái cây chín mọng ép nước.</p></li><li><p data-path-to-node=\"9,1,1,3,0\" style=\"margin: 0px 0px 15px;\"><i data-index-in-node=\"0\" data-path-to-node=\"9,1,1,3,0\">Hậu vị :</i> Kéo dài vừa phải, để lại cảm giác khoáng đạt, sạch vòm họng và thoảng hương vỏ cam quýt.</p></li></ul></li></ul><p data-path-to-node=\"9,1,1,3,0\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\"><span data-index-in-node=\"0\" data-path-to-node=\"10,0\" style=\"font-weight: bolder;\">Tổng kết phong cách:</span> Kimi mang phong cách Marlborough điển hình với acid sắc nét, hương trái cây nhiệt đới rõ rệt và hậu vị sạch, không hề bị đắng hay gắt cồn.</p><h2 data-path-to-node=\"24\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Kimi Sauvignon Blanc kết hợp món gì ngon?</h2><p data-path-to-node=\"25\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Độ acid cao và hương vị cam quýt của Kimi hoạt động giống như một \"vắt chanh ảo\", giúp nâng tầm hương vị cho rất nhiều món ăn:</p><ul data-path-to-node=\"26\" style=\"margin-bottom: 15px; list-style: initial; padding-left: 25px; font-family: Roboto, sans-serif; font-size: 14px;\"><li><p data-path-to-node=\"26,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"26,0,0\" style=\"font-weight: bolder;\">Hải sản (Lựa chọn hàng đầu):</span> Vị chua sắc nét cắt phăng vị ngậy béo của hàu sống, tôm hấp hay sò điệp áp chảo, giúp hải sản dậy lên vị ngọt tự nhiên.</p></li><li><p data-path-to-node=\"26,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"26,1,0\" style=\"font-weight: bolder;\">Món Nhật:</span> Sự tinh tế của ẩm thực Nhật như Sushi và Sashimi cá hồi, cá trích ép trứng cực kỳ ăn ý với cấu trúc sạch sẽ của Kimi.</p></li><li><p data-path-to-node=\"26,2,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"26,2,0\" style=\"font-weight: bolder;\">Món ăn Việt Nam:</span> Bạn có thể tự tin kết hợp chai vang này với các món gỏi hải sản chua cay, cá chẽm hấp hành gừng hoặc salad xoài xanh tai heo. Bạn có thể tham khảo thêm các dòng <a href=\"https://wine1855.vn/vang-trang\" style=\"text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-weight: bold; color: rgb(201, 76, 62) !important;\">rượu vang trắng ngon</a><a data-ved=\"0CAAQ_4QMahgKEwiBz4mDwt2UAxUAAAAAHQAAAAAQ7gE\" data-hveid=\"0\" class=\"ng-star-inserted\" href=\"https://wine1855.vn/\" rel=\"noopener\" decode-data-ved=\"1\" jslog=\"197247;track:generic_click,impression,attention;BardVeMetadataKey:[[&quot;r_bc76a934e11e2e18&quot;,&quot;c_6086657242d5b913&quot;,null,&quot;rc_f7288788430a66d5&quot;,null,null,&quot;&quot;,null,1,null,null,1,0]]\" _nghost-ng-c316779397=\"\" externallink=\"\" target=\"_blank\" _ngcontent-ng-c3199444370=\"\" data-mce-href=\"https://wine1855.vn/\" style=\"text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-weight: bold; color: rgb(201, 76, 62) !important;\"></a> để đa dạng hóa thực đơn cho bữa tiệc của mình.</p></li><li><p data-path-to-node=\"26,3,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"26,3,0\" style=\"font-weight: bolder;\">Phô mai :</span> Hợp nhất là phô mai dê (Goat cheese) hoặc phô mai Feta. Vị chua trong rượu sẽ làm cân bằng cấu trúc phấn béo đặc trưng của loại cheese này.</p></li></ul><h2 data-path-to-node=\"28\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Cách uống ngon nhất</h2><p data-path-to-node=\"29\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Để Kimi bộc lộ toàn bộ \"vũ điệu hương vị\" của mình, hãy tuân thủ các nguyên tắc phục vụ thực tế sau:</p><ul data-path-to-node=\"30\" style=\"margin-bottom: 15px; list-style: initial; padding-left: 25px; font-family: Roboto, sans-serif; font-size: 14px;\"><li><p data-path-to-node=\"30,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"30,0,0\" style=\"font-weight: bolder;\">Nhiệt độ phục vụ lý tưởng:</span> Bạn nên ướp lạnh trong xô đá khoảng 30 phút hoặc để ngăn mát tủ điện ảnh hưởng trước 2 tiếng. Không nên uống quá ấm vì rượu sẽ bị nồng cồn và mất đi độ giòn (crisp).</p></li><li><p data-path-to-node=\"30,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"30,1,0\" style=\"font-weight: bolder;\">Loại ly:</span> Sử dụng ly vang trắng tiêu chuẩn (ly có bầu nhỏ, thuôn gọn về phía miệng) để giữ cho hương thơm tập trung thẳng vào khứu giác và duy trì nhiệt độ lạnh lâu hơn.</p></li><li><p data-path-to-node=\"30,2,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"30,2,0\" style=\"font-weight: bolder;\">Có cần Decanter không?:</span> <span data-index-in-node=\"33\" data-path-to-node=\"30,2,0\" style=\"font-weight: bolder;\">Không cần.</span> Đây là dòng vang trẻ, hướng đến sự tươi mát. Bạn chỉ cần khui nắp và thưởng thức ngay để tận hưởng hương thơm nguyên bản.</p></li><li><p data-path-to-node=\"30,3,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"30,3,0\" style=\"font-weight: bolder;\">Thời điểm uống đẹp nhất:</span> Nên uống trong vòng 1–3 năm kể từ niên vụ (vintage) in trên nhãn chai để cảm nhận rõ nhất vị trái cây tươi.</p></li></ul><h2 data-path-to-node=\"32\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Kimi Sauvignon Blanc phù hợp với ai?</h2><p data-path-to-node=\"33\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Kimi Sauvignon Blanc không dành cho tất cả mọi người, nó được thiết kế để phục vụ hoàn hảo cho một nhóm gu thưởng thức nhất định:</p><h3 data-path-to-node=\"34\" style=\"margin-bottom: 0.5rem; font-weight: 500; line-height: 1.4; font-size: 1.75rem; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Phù hợp nếu bạn:</h3><ul data-path-to-node=\"35\" style=\"margin-bottom: 15px; list-style: initial; padding-left: 25px; font-family: Roboto, sans-serif; font-size: 14px;\"><li><p data-path-to-node=\"35,0,0\" style=\"margin: 0px 0px 15px;\">Yêu thích phong cách vang trắng tươi tắn, thanh mát và giàu hương thơm trái cây.</p></li><li><p data-path-to-node=\"35,1,0\" style=\"margin: 0px 0px 15px;\">Là \"fan cứng\" của các dòng <a href=\"https://wine1855.vn/ruou-vang-new-zealand\" style=\"text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-weight: bold; color: rgb(201, 76, 62) !important;\">rượu vang Marlborough New Zealand</a> đặc trưng.</p></li><li><p data-path-to-node=\"35,2,0\" style=\"margin: 0px 0px 15px;\">Tìm kiếm một chai vang dễ tiếp cận, dễ uống, không cần phải suy nghĩ hay phân tích quá sâu khi thưởng thức.</p></li><li><p data-path-to-node=\"35,3,0\" style=\"margin: 0px 0px 15px;\">Thường xuyên ăn các món hải sản hoặc đồ sống.</p></li></ul><h3 data-path-to-node=\"36\" style=\"margin-bottom: 0.5rem; font-weight: 500; line-height: 1.4; font-size: 1.75rem; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Có thể KHÔNG phù hợp nếu bạn:</h3><ul data-path-to-node=\"37\" style=\"margin-bottom: 15px; list-style: initial; padding-left: 25px; font-family: Roboto, sans-serif; font-size: 14px;\"><li><p data-path-to-node=\"37,0,0\" style=\"margin: 0px 0px 15px;\">Tìm kiếm một chai vang trắng béo ngậy, dậy mùi bơ mứt kiểu Chardonnay vùng Napa Valley.</p></li><li><p data-path-to-node=\"37,1,0\" style=\"margin: 0px 0px 15px;\">Thích vang có hương gỗ sồi đậm đà và có hậu vị chát nhẹ.</p></li></ul>', NULL, 1, 0, '2026-06-02 01:30:05', NULL, NULL, 1, NULL, NULL, '', 2, 'Rượu Vang Kimi Sauvignon Blanc - New Zealand', 'Kimi Marlborough Sauvignon Blanc là một trong những đại diện tiêu biểu cho phong cách vang trắng hiện đại của New Zealand, nổi bật với hương thơm mãnh liệt độc bản và độ chua', NULL, '', '', 0, '[]', '[]', NULL, 0, 1, 'visible');
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `old_price`, `abv`, `volume`, `grape_type`, `wine_type`, `region`, `country`, `description`, `producer_id`, `status`, `featured`, `created_at`, `schedule_start`, `schedule_end`, `product_type`, `spirit_type`, `brand`, `age`, `stock_quantity`, `seo_title`, `seo_description`, `seo_keywords`, `sku`, `barcode`, `weight_gram`, `dynamic_attributes`, `variants`, `tags`, `requires_special_shipping`, `auto_status_update`, `display_status`) VALUES
(95, 'Rượu Vang Pháp Château Dauzac 2015', 'ruou-vang-phap-chateau-dauzac-2015', '99999999.99', NULL, '', '', '', NULL, '', '', '<h2 data-end=\"692\" data-start=\"653\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\"><span data-end=\"412\" data-start=\"386\" style=\"font-weight: bolder; font-size: 14px;\">Château Dauzac Margaux</span><span style=\"font-size: 14px;\"> là một trong những điền trang </span><span style=\"font-weight: bolder; font-size: 14px;\"><a href=\"https://wine1855.vn/ruou-vang\" style=\"text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-weight: bold; color: rgb(201, 76, 62) !important;\"><span style=\"color: rgb(231, 76, 60);\">rượu vang</span></a></span><span style=\"font-size: 14px;\"> danh tiếng nhất tại vùng Bordeaux, Pháp. Với lịch sử lâu đời và vị trí đắc địa nằm cạnh sông Gironde, điền trang này sở hữu điều kiện khí hậu và thổ nhưỡng lý tưởng để sản xuất rượu vang đỏ cao cấp.</span></h2><h2 data-end=\"692\" data-start=\"653\" style=\"text-align: center; line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\"><img src=\"https://ruouchat.vn/api/../uploads/product_desc/2026/06/20260617_142108_736da3e80415a73a.webp\" alt=\"ruou vang phap chateau dauzac\" style=\"max-width:100%\"><span style=\"font-size: 14px;\"><br></span></h2><h2 data-end=\"692\" data-start=\"653\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Vị trí và điều kiện tự nhiên nổi bật</h2><p data-end=\"1039\" data-start=\"694\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Château Dauzac nằm ở phía Nam của vùng <span data-end=\"744\" data-start=\"733\" style=\"font-weight: bolder;\">Margaux</span>, gần sông Gironde. Nhờ đó, nơi đây có khí hậu ấm áp, ôn hòa, rất thích hợp cho việc trồng các giống nho như <a href=\"https://wine1855.vn/cabernet-sauvignon\" style=\"text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-weight: bold; color: rgb(201, 76, 62) !important;\"><span data-end=\"875\" data-start=\"853\" style=\"font-weight: bolder;\">Cabernet Sauvignon</span></a> và <a href=\"https://wine1855.vn/merlot\" style=\"text-decoration: none; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-weight: bold; color: rgb(201, 76, 62) !important;\"><span data-end=\"889\" data-start=\"879\" style=\"font-weight: bolder;\">Merlot</span></a>. Đất đai tại điền trang chủ yếu là sỏi đá lâu năm, giúp rễ nho phát triển sâu và ổn định, góp phần tạo nên hương vị rượu đậm đà, cân bằng và tinh tế.</p><p data-end=\"1039\" data-start=\"694\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">fdfdfdf</p><h2 data-end=\"1084\" data-start=\"1041\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Quá trình sản xuất rượu vang đỏ Château Dauzac 2015</h2><p data-end=\"1215\" data-start=\"1086\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Tại Château Dauzac, quá trình trồng nho và sản xuất rượu vang luôn tuân thủ các tiêu chuẩn bền vững và thân thiện với môi trường.</p><ul data-end=\"1548\" data-start=\"1217\" style=\"margin-bottom: 15px; list-style: initial; padding-left: 25px; font-family: Roboto, sans-serif; font-size: 14px;\"><li data-end=\"1310\" data-start=\"1217\"><p data-end=\"1310\" data-start=\"1219\" style=\"margin: 0px 0px 15px;\">Nho được <span data-end=\"1258\" data-start=\"1228\" style=\"font-weight: bolder;\">chọn lọc thủ công kỹ lưỡng</span> qua nhiều giai đoạn để đảm bảo chất lượng cao nhất.</p></li><li data-end=\"1421\" data-start=\"1311\"><p data-end=\"1421\" data-start=\"1313\" style=\"margin: 0px 0px 15px;\">Sau khi thu hoạch, nho được <span data-end=\"1382\" data-start=\"1341\" style=\"font-weight: bolder;\">ép lạnh trong các thùng thép không gỉ</span> nhằm giữ trọn vẹn hương thơm tự nhiên.</p></li><li data-end=\"1548\" data-start=\"1422\"><p data-end=\"1548\" data-start=\"1424\" style=\"margin: 0px 0px 15px;\">Rượu được <span data-end=\"1488\" data-start=\"1434\" style=\"font-weight: bolder;\">ủ trong thùng gỗ sồi Pháp mới (50%) trong 12 tháng</span>, giúp tạo nên cấu trúc tannin mềm mại và hương vị phức hợp.</p></li></ul><p data-end=\"1782\" data-start=\"1550\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Đặc biệt, Château Dauzac <span data-end=\"1613\" data-start=\"1575\" style=\"font-weight: bolder;\">hạn chế tối đa việc sử dụng sulfur</span> và không sử dụng lòng trắng trứng để lọc rượu. Thay vào đó, họ dùng nguyên liệu có nguồn gốc thực vật, giúp rượu đạt chuẩn <span data-end=\"1751\" data-start=\"1737\" style=\"font-weight: bolder;\">vegan wine</span> (vang thuần chay) từ năm 2016.</p>', NULL, 1, 0, '2026-06-17 07:22:23', NULL, NULL, 1, NULL, NULL, '', 50, 'Rượu Vang Pháp Château Dauzac 2015 | Ruouchat.vn', 'Château Dauzac Margaux là một trong những điền trang rượu vang danh tiếng nhất tại vùng Bordeaux, Pháp. Với lịch sử lâu đời và vị trí đắc địa nằm cạnh sông Gironde', NULL, 'VD/0166', '', 0, '[]', '[]', NULL, 0, 1, 'visible'),
(99, 'Bia Bỉ Kristoffel Dark 6%', 'bia-bi-kristoffel-dark-6', '4500000.00', NULL, '', '', '', NULL, '', '', '<p data-path-to-node=\"12\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Trong thế giới của những người sành sỏi thức uống đại mạch, bia Bỉ luôn chiếm giữ một vị thế tôn nghiêm nhờ phương thức ủ men đặc trưng và chiều sâu văn hóa không thể thay thế. Giữa hàng trăm thương hiệu danh tiếng, bia Bỉ Kristoffel Dark 6% loại chai 330ml nổi lên như một biểu tượng trường tồn của dòng bia nâu mang phong cách tu viện (Abbey-style Brown Ale). Đây không chỉ là một thức uống giải khát thông thường, mà là một tác phẩm nghệ thuật tinh tế, kết tinh từ những nguyên liệu chọn lọc và kỹ nghệ lên men nổi (top fermentation) bậc thầy của vùng đất Flanders.</p><p data-path-to-node=\"12\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><img src=\"https://bizweb.dktcdn.net/100/441/574/files/nem-thu-huong-vi-bia-den-kristoffel.jpg?v=1781003977500\" style=\"border: 0px; max-width: 100%; height: auto !important;\"></p><p data-path-to-node=\"12\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><span style=\"font-weight: bolder;\">Bia Bỉ Kristoffel Dark Chính Hãng</span></p><h2 data-path-to-node=\"13\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Nguồn gốc lịch sử và di sản lâu đời từ nhà máy Brouwerij Martens</h2><p data-path-to-node=\"14\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Để thấu hiểu được sự sâu sắc trong từng ngụm bia Kristoffel Dark, chúng ta phải quay ngược thời gian trở về vùng Limburg, Bỉ, nơi nhà máy bia Brouwerij Martens được thành lập vào năm 1758. Với lịch sử kéo dài gần ba thế kỷ, Martens là một trong số ít những nhà máy gia đình còn gìn giữ được vẹn nguyên những bí truyền nấu bia cổ điển từ thời trung cổ, đồng thời kết hợp nhuần nhuyễn với công nghệ kiểm soát chất lượng hiện đại.</p><p data-path-to-node=\"15\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Cái tên Kristoffel được đặt theo tên của Thánh Christopher (St. Kristoffel) – vị thánh bảo hộ cho những người lữ hành trong văn hóa dân gian địa phương tại vùng Bocholt. Hình ảnh của vị thánh gắn liền với những câu chuyện về lòng kiên định, sự bảo bọc và tinh thần khám phá. Việc lấy tên Ngài đặt cho dòng bia chủ lực là lời khẳng định của nhà Martens về một dòng bia mang lại sự an yên, hứng khởi và niềm hạnh phúc trọn vẹn cho bất kỳ ai thưởng thức. Kristoffel Dark chính là đại diện cho tinh thần gìn giữ di sản đó, một chai bia mang đậm hơi thở của những dòng bia Dubbel cổ điển từng được các tu sĩ chăm chút trong các tu viện xa xưa.</p><h2 data-path-to-node=\"16\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Thông số kỹ thuật và đặc tính cốt lõi của chai bia Kristoffel Dark 330ml</h2><p data-path-to-node=\"17\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Sự chuyên nghiệp và chuẩn mực của Kristoffel Dark được thể hiện rõ ràng qua các chỉ số kỹ thuật được nhà sản xuất công bố. Việc nắm rõ các thông số này giúp người thưởng thức định hình trước cấu trúc của dòng sản phẩm:</p><ul data-path-to-node=\"18\" style=\"margin-bottom: 15px; list-style: initial; padding-left: 25px; font-family: Roboto, sans-serif; font-size: 14px;\"><li><p data-path-to-node=\"18,0,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"18,0,0\" style=\"font-weight: bolder;\">Xuất xứ:</span> Vương quốc Bỉ (Belgium)</p></li><li><p data-path-to-node=\"18,1,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"18,1,0\" style=\"font-weight: bolder;\">Nhà sản xuất:</span> Brouwerij Martens</p></li><li><p data-path-to-node=\"18,2,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"18,2,0\" style=\"font-weight: bolder;\">Phong cách:</span> Belgian Dubbel / Dark Abbey Ale</p></li><li><p data-path-to-node=\"18,3,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"18,3,0\" style=\"font-weight: bolder;\">Nồng độ cồn (ABV):</span> 6.0%</p></li><li><p data-path-to-node=\"18,4,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"18,4,0\" style=\"font-weight: bolder;\">Chỉ số độ đắng (IBU):</span> 24</p></li><li><p data-path-to-node=\"18,5,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"18,5,0\" style=\"font-weight: bolder;\">Dung tích:</span> Chai thủy tinh 330ml (Quy cách thùng 24 chai)</p></li><li><p data-path-to-node=\"18,6,0\" style=\"margin: 0px 0px 15px;\"><span data-index-in-node=\"0\" data-path-to-node=\"18,6,0\" style=\"font-weight: bolder;\">Thành phần chính:</span> Nước tinh khiết, mạch nha đại mạch rang (roasted malt), bắp, hoa bia tuyển chọn và men bia đặc chủng nước Bỉ.</p></li></ul><p data-path-to-node=\"19\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Dung tích 330ml được xem là tỷ lệ vàng dành cho các dòng bia nặng tính trải nghiệm. Nó vừa vặn để giữ cho nhiệt độ của bia không bị thay đổi quá nhiều từ lúc mở nắp cho đến giọt cuối cùng trong ly, bảo toàn trọn vẹn cấu trúc hương vị.</p><p data-path-to-node=\"19\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><img src=\"https://bizweb.dktcdn.net/100/441/574/files/bia-nau-kristoffel-dark.jpg?v=1781004060607\" style=\"border: 0px; max-width: 100%; height: auto !important;\"></p><p data-path-to-node=\"19\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px; text-align: center;\"><span style=\"font-weight: bolder;\">Bia Bỉ Kristoffel Dark Kết Hợp Vơi Hàu Nướng</span></p><h2 data-path-to-node=\"20\" style=\"line-height: 1.4; color: rgb(0, 0, 0); font-family: Roboto, sans-serif;\">Hành trình giải mã các tầng hương vị độc đáo của Kristoffel Dark</h2><p data-path-to-node=\"21\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Thưởng thức Kristoffel Dark là một hành trình đánh thức mọi giác quan, nơi mà người uống cần chậm lại để cảm nhận sự chuyển dịch tinh tế của từng làn hương, lớp vị.</p><p data-path-to-node=\"22\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Ngay khi được rót ra ly, dòng bia hiện ra với một sắc nâu hổ phách sẫm đậm đà, ánh lên những tia đỏ ruby huyền ảo khi soi dưới nguồn sáng. Lớp bọt bia màu trắng ngà, dày dặn và mịn màng như kem, chậm rãi tan ra và để lại những vệt chân bia (lace) bám chặt vào thành ly – một dấu hiệu minh chứng cho hàm lượng chất chiết từ mạch nha cực kỳ cao và kỹ thuật ủ bia đạt chuẩn.</p><p data-path-to-node=\"23\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Về khứu giác, luồng hương đầu tiên xộc vào mũi là sự ấm áp, ngọt ngào của caramel và đường nâu nướng. Kế tiếp, khi hương bia được giải phóng hoàn toàn trong không khí, bạn sẽ nhận ra mùi thơm trầm ấm của bánh mì nướng cháy nhẹ, đan xen với cacao, socola đắng và thoang thoảng hương vị trái cây khô như nho chín hay mận sẫm màu. Sự phức hợp này hoàn toàn tách biệt Kristoffel Dark khỏi những dòng bia đen công nghiệp vốn thường chỉ có một mùi mạch nha đơn điệu.</p><p data-path-to-node=\"23\" style=\"text-align: center; margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\"><img src=\"https://ruouchat.vn/api/../uploads/product_desc/2026/06/20260622_112352_60c8bf027184986f.webp\" alt=\"uop lanh bia bi kristoffel dark truoc khi uong\" style=\"max-width: 100%; width: 100%;\"><br></p><p data-path-to-node=\"24\" style=\"margin: 0px 0px 15px; font-family: Roboto, sans-serif; font-size: 14px;\">Khi ngụm bia đầu tiên chạm vào vòm miệng, cảm giác thân bia (body) mượt mà, đầy đặn bao phủ toàn bộ cơ quan vị giác. Vị ngọt dịu từ mạch nha rang và caramel xuất hiện đầu tiên, tạo cảm giác êm ái, tròn trịa. Ngay sau đó, độ cồn 6% phát huy vai trò như một chất xúc tác, làm ấm khoang miệng và đẩy các tầng hương gia vị lên cao. Điểm đắt giá nhất của Kristoffel Dark nằm ở hậu vị: kết thúc bằng một cảm giác khô nhẹ, vị đắng thanh thoát từ hoa bia (IBU 24) cân bằng hoàn hảo với vị ngọt ban đầu, để lại dư vị kéo dài của socola và hạt hạnh nhân nướng thơm lừng.</p>', NULL, 1, 0, '2026-06-22 04:37:39', NULL, NULL, 5, NULL, NULL, '', 2, '', '', NULL, '', '', 0, '[]', '[]', NULL, 0, 1, 'visible');
